INSERT INTO public.species_en (species_id, scientific_name, common_name, etymology, habitat, identification_character, leaf_type, fruit_type, phenology, seed_germination, pest, definition) VALUES
(1, 'Aleurites moluccana', 'Ai-Kami', 'Aleurites is from Greek aleuron meaning “flour/meal,” referring to a mealy coating, and moluccana means “from the Moluccas (Maluku Islands, Indonesia)', 'Common from coast to mid-hills in Timor-Leste, growing in secondary forest, along streams  and on open hilly roadsides.', 'A medium–large tree; leaves alternate, large, simple and often 3-lobed (especially on young shoots), underside pale/silvery; leaf stalk very long; sap milky; flowers white in branching clusters; fruit a hard-shelled drupe ~4–6 cm, green when young, turning brown-black when ripe, with 1–2 oily “candlenuts.”', 'Simple', 'Drupe', 'Throughout the Year', 'Collect brown mature fruits from the tree or dry endocarp. Extract seed by softening fresh fruits a few days, peeling the rind, washing, and drying; discard floaters in water and store dried seed for months at ~10–12% moisture. Because the endocarp is very hard, sun-dry the shells 2–3 days and then plunge warm shells into water (thermal shock) to crack them; protect seeds from rodents. Use a germination medium of roughly 2:1 topsoil to river sand, and sow cracked nuts 2–3 cm deep in deep polybags or a loose, deep bed (large taproot). With cracking, germination typically occurs in ~3–8 weeks (some in 3–4 weeks) and rates can exceed 80%, whereas untreated seeds may take 3–4 months and often rot.', 'For candlenut, the most immediate nursery threat is rodents drawn to the oily kernels - protect germination beds and trays with wire mesh or fine netting and keep floors clean. In the field, fungal diseases cause defoliation and premature fruit drop, while longhorn stem borers and subterranean termites damage stems, collars, and roots. Fruits are frequently attacked by fruit flies and seed/pod borers; regular collection and destruction of fallen or infested fruits is essential.', NULL),
(2, 'Tectona grandis', 'Ai-Teka', 'Tectona comes from Greek téktōn “carpenter/builder,” hinting at use as timber, and grandis is Latin for large/great.', 'Mostly planted and sometimes naturalised on dry hills and limestone ridges', 'A large, deciduous tree; leaves very large, opposite and simple; sheds leaves for 3–4 months in the late dry season; flowers small (≈8 mm), mauve to white, in large branched heads; fruit a round, hard, woody drupe with four chambers, enclosed in an inflated, papery “bladder,” pale green then brown at maturity.', 'Simple', 'Drupe', 'Flowering: June to September; Fruiting: November to January', 'Collect mature, dry fruits; remove the outer sepals/calyx, then lightly scarify the hard shell with sandpaper or a rough stone. Fill polybags with a well-draining mix of soil and compost in a 3:1 ratio. Sow 3–5 seeds per bag at 1–2 cm depth or sow in germination bed first.', 'Termites are the main stem problem in teak; they eat into the heartwood, leaving hollow stems and mud galleries- once badly attacked, felling and burning is the only practical option. Leaf-eating caterpillars can strip foliage fast; do frequent inspections, keep crowns open with light pruning, and remove heavily infested leaves/branches. Wood borers make small round holes and push out sawdust-like powder; avoid wounding trees and remove/destroy infested wood. In nurseries and young plantings, sudden wilt often follows poor drainage or rough root handling - use well-drained beds, water evenly, and prune out any cankered/dying shoots below the last symptom.', NULL),
(3, 'Toona ciliata', 'Ai-Saria', 'Toona is from the Indian vernacular name “toon/tun” for the tree, and ciliata is Latin for “fringed/hairy,” referring to fine hairs on parts like leaf edges', 'it grows along moist streams and ravines on well-drained fertile soils from near sea level up to about 1,500 m', 'A tall, deciduous tree;  trunk often buttressed, outer bark dark brown, rough and scaly;  leaves alternate and single pinnate with 4–8 opposite to subopposite pairs of lanceolate leaflets, new foliage bright pink; flowers small, white and fragrant, in long drooping terminal sprays; fruit a dry 5-valved capsule that splits from the top to release many small, winged seeds.', 'Pinnately compound (single)', 'Capsule', 'Flowering: March - May; Fruiting: July - August', 'Collect ripe, fully mature fruits from the tree when the fruit start splitting. Fill nursery beds with a well-drained mix of topsoil plus compost or sand. Surface-sow or cover very lightly in rows 10 cm apart;', 'Young toon (Toona ciliata) often suffers from shoot borers that kill the top shoot and cause forks and crooked crowns; check tips often, keep one straight leader, and cut-and-burn infested shoots. Termites and powderpost beetles attack the wood, leaving small round holes and flour-like dust - avoid wounding, keep timber off the ground, and remove badly infested pieces. Parasitic mistletoe appears as green clumps on branches; lop the branch back to healthy wood and destroy the clumps. Root and butt rots weaken trees (yellowing leaves, leaning stems, shelf-like mushrooms at the base); keep the stem base dry and uninjured, and remove badly rotted trees. Protect seedlings and saplings from cattle  with simple guards or fencing until they are well established.', NULL),
(4, 'Sterculia foetida', 'Ai-nitas', 'Sterculia derives from Latin Sterculius, the Roman manure god (stercus = dung), and foetida is Latin for “bad-smelling/fetid.', 'A lowland tree of hot, dry coastal plains and rocky slopes, often near villages and along roads.', 'A large, straight, deciduous tree; bark smooth and grey; leaves crowded at twig tips, palmately digitate with 7–9 leaflets, petiole long (to ~20 cm) and foliage with an unpleasant smell; flowers in many branch stalk, green to dull purple, with male and female on separate trees; fruit a cluster of thick red follicles that become woody, each bearing several slate-coloured, oblong seeds (~1.5–1.8 cm) with a small yellow aril.', 'Palmately compound', 'Follicle', 'Flowering: February to March, Fruiting: January to February. Fruits ripen nearly 11 months after the first appearance of the flowers.', 'Collect mature red fruit and split the fruit to extract black seeds, remove the seeds and wash off all pulp to avoid fungus. Soak seeds for 24 hours, then peel the thin black coat or lightly scarify instead. Plant in a germination bed with well-drained mix of black soil and compost in a 3:1 ratio. Lay the seed on its side or plant it so the scarified/nicked end is level with or slightly above the surface.', 'In nurseries of Sterculia foetida, the main problem is a leaf-rolling caterpillar that can hit 70–80% of seedlings and cause very high death rates. The larvae stitch the leaf with fine silk, roll it up, and feed inside, leaving thin “windowed” patches between the veins before moving to fresh leaves. Check beds daily and remove or destroy rolled leaves with the caterpillar inside. Protect germination beds with fine insect mesh, keep spacing and airflow good, and avoid over-lush, shaded growth. At first signs, a biological spray like a neem (azadirachtin) spray can help keep damage down.', NULL),
(5, 'Albizia lebbeck', 'Ai-Samatuku', 'Albizia honors Filippo degli Albizzi, who introduced an Albizia to Europe, and lebbeck comes from the local Arabic/Indic name “lebbek/labakh', 'The species grows along hilly roadsides at low to mid elevations.', 'A medium–large, deciduous tree; bark grey, fissured and corky, leaves double pinnate with 2–4 pairs of pinnae, each bearing many small obliquely oblong leaflets (~1.5–6.5 × 0.5–3.5 cm); flowers in large, fragrant, fluffy, yellow-green spherical heads on long stalks; fruit is long, flat, papery-leathery pods , pale straw to light brown, swollen over the seeds and not constricted.', 'Pinnately compound (double)', 'Pod', 'Flowering: September–November; Fruiting: May–July', 'Collect pods when they’re dry, light brown, and before they split; sun-dry a few days so they open, then clean and store seeds dry. Pre-treat by pouring just-boiled water over the seeds and soak 12–24 hours to soften the hard coat. Fill germination bed  with Soil : Sand : Compost in a 1:1:1 mix. Sow ~1 cm deep; in beds space seeds ~5 cm apart in rows, germination usually starts in about 1–2 weeks with fresh, pre-treated seed.', 'In nurseries, Albizia seedlings often die from damping-off and other root rots; use clean, well-drained media, avoid over-watering, and discard sick plants early. In the field, a serious wilt disease can block water flow, leading to yellowing leaves, sudden dieback, and death of branches or whole trees; remove badly affected trees and avoid wounding roots and stems.', NULL),
(6, 'Azadirachta indica', 'Sumaer Malae', 'Azadirachta is from Persian azad-darakht meaning “free tree” (noble or not subject to pruning), and indica denotes “from India', 'The species grows on barren lands and is commonly planted along roadsides.', 'Azadirachta indica is a medium to large evergreen tree, with a dense rounded crown and dark grey, fissured bark. Leaves are tri pinnately compound, 20–40 cm long,  Flowers are small, white to pale yellow, fragrant, and borne in branches. The fruit is a 1-seeded ellipsoidal drupe, greenish-yellow to purple when ripe. The tree begins fruiting after 5 years and can live up to 200 years.', 'Pinnately compound (Single)', 'Drupe', 'Flowering: January–March; Fruiting: May–August', 'Neem fruits are collected when they turn yellow and slightly soft, preferably harvested directly from the tree. After depulping and cleaning, the seeds should be sown fresh, as they lose viability quickly and do not require scarification. A soil:sand:compost mix of 2:1:2 provides the best medium, with seeds sown 1–2 cm deep in polybags or raised beds. Germination usually begins within 4–10 days and is mostly complete in 3–5 weeks. Fresh seeds have the highest success rate, while older seeds show reduced germination.', 'Neem trees are usually resistant, but some pests and diseases do affect them. In nurseries, seedlings often suffer from damping off (caused by fungi) and leaf spots from different fungi and bacteria. Root rot and pink disease can damage older trees, causing branch dieback.', NULL),
(7, 'Acacia mangium', 'Akasia', 'Acacia is from Greek akis (“point/barb”), referring to spines/thorns in the group, and mangium comes from the Moluccan common name used for this tree.', 'The species grows best on degraded lands and is suitable for land rehabilitation, though it is not very common naturally.', 'A medium–large fast-growing tree with a broad crown; leaves alternate and large, leaf thick, dark green with 3–5 strong parallel veins; bark brown to dark brown and rough on older trees; flowers small cream–pale yellow in long slender spikes; fruit a long flat pod ~7–15 cm, green then dark brown/black, often twisting when dry and splitting open; seeds many, small hard shiny black, often with a small orange/yellow tip;', 'Simple', 'Pod', 'Flowering: July to August; Fruiting: December to February', 'Acacia mangium pods are collected when fully dry, dark brown to black, and twisted, preferably picked from the tree before they split (in Timor-Leste usually October to April). Pods can be sun-dried to help them open for easy seed extraction. Because seeds have a hard coat, scarify before sowing, ideally by dipping in near-boiling water for ~30 seconds and then soaking in cool water for 24 hours, which can give about 75–90% germination. Sow 0.5–1 cm deep in a well-draining medium (e.g., sandy loam with compost) in polybags or nursery beds. With pre-treatment, germination starts within 1 week and is mostly complete in 2–3 weeks; without it, germination is slow and uneven. Provide light shade for 2–4 weeks, avoid waterlogging, thin to one seedling per bag, and transplant at 3–4 months when seedlings are ~25–40 cm tall.', 'Acacia mangium often gets heart rot and pink disease, and older or weak trees can also be badly damaged by wood-boring insects and termites, which can weaken the stem and reduce wood quality. Heart rot is usually hidden inside the trunk and often starts from old branch cuts or wounds, so prevent it with clean early pruning. Pink disease shows pink patches on branches or the stem, causing branch dieback and sometimes breakage, so reduce it by not planting too close, thinning on time for better airflow, and keeping trees healthy with good site care and weed control. For both problems, remove and destroy infected branches, clean tools, and remove badly damaged trees early to stop spread.', NULL),
(8, 'Alstonia scholaris', 'Ai‑hanek/Rito', 'Alstonia commemorates botanist Charles Alston, and scholaris is Latin for “of schools,” referring to the wood’s traditional use for making writing slates/blackboards.', 'The species occurs naturally across Timor-Leste, especially along roadside areas and seasonal streams.', 'A very tall tree with a thick trunk, when cut or injured it releases white sticky sap; leaves long and smooth, grouped in rings of 4–8 at one point on the stem; flowers in branched clusters at branch ends, small white/cream and strongly fragrant; fruit long, very slender, pencil-like pods that usually come in pairs, green then brown when dry, splitting open to release many seeds; seeds very light with silky hairs, easily carried by wind. The species can be identifed from the 4–8 ring-like leaves on a node and long paired pod-like fruit with silky seeds.', 'Simple', 'Follicle', 'Flowering:May-June; Fruiting: June-July', 'Alstonia scholaris fruits are long, slender paired follicles that hang in a V-shape and mature when they turn from green to brown, become dry and slightly twisted, and begin to split. In Timor-Leste, fruits usually mature from June to September. For clean collection, cut fruiting twigs or follicle clusters just before they open and dry them in paper or mesh bags, or tie mesh bags around on-tree follicles to catch seeds at dehiscence; avoid wet fruits to reduce mold. Seeds are minute, wind-dispersed with silky hairs, and they lose viability within a few months, so use fresh seed and no pre-treatment is needed. Sow seeds on the surface of a fine, moist bed or tray without burying, pressing lightly or covering with a very thin dusting of sand. Germination often starts in 7–10 days and is mostly complete in about 2 weeks. Keep seedlings under ~50% shade, mist lightly, control weeds, and transplant to polybags after 4–6 weeks.', 'Alstonia scholaris often suffers from leaf-eating caterpillars when young, and later the wood can be damaged by termites and small borers, which weakens the tree and lowers timber quality. Reduce problems by checking trees regularly, removing and destroying badly affected leaves/branches, keeping the area clean, and keeping trees healthy with good spacing and basic care. If wood is cut, dry and store it properly and remove any infested pieces early to stop spread.', NULL),
(9, 'Calophyllum inophyllum', 'Too/Samplon', 'Calophyllum is from Greek kalos (“beautiful”) + phyllon (“leaf”), and inophyllum is Greek, referring to the tree’s closely nerved/veined leaves.', 'Calophyllum inophyllum grows abundantly along coastal areas, especially around Dili and Baucau.', 'Calophyllum inophyllum is a medium–large evergreen coastal tree, with a stout straight trunk and a dense, rounded spreading crown; leaves simple, thick and glossy, oval, with many fine parallel veins; flowers small, white to creamy and very fragrant, in clusters; fruit a round green “nut-like” drupe about 2–4 cm across that turns yellowish-brown when ripe, with a hard seed inside; The species can be identified from the shiny thick oval leaves with many close parallel veins, fragrant white flowers, and round green-to-brown fruits.', 'Simple', 'Drupe', 'Flowering: April-May; Fruiting: June-August', 'Calophyllum inophyllum fruits are round drupes (3–5 cm) that ripen from green and firm to yellow-green/brown with slightly soft flesh, enclosing one seed inside a hard woody stone. In Timor-Leste, collect mature fruits from June to August, preferably from the tree or freshly fallen the same day; rinse beach-collected fruits in fresh water to remove salt. Depulp by soaking overnight, peeling off the flesh, washing, and shade-drying briefly. Seeds will germinate without pre-treatment, but intact shells cause slow, staggered germination over 2–4 months. For faster, more uniform results, remove the husk and gently crack the woody shell to fracture it, which can reduce germination to about 3–8 weeks. Sow 1–3 cm deep in polybags (one per bag) or spaced beds, using a well-draining mix such as compost:sand:rice husk (1:1:1) under ~50% shade. Keep evenly moist, avoid waterlogging, shift seedlings to full sun by ~2 months, and plant out at 5–6 months (~25–30 cm tall) at the start of rains.', 'Calophyllum inophyllum is usually a tough coastal tree, but young plants and fruiting trees can still lose leaf area and give less fruit/oil if pests build up. Leaf miners make thin lines or patchy “tunnels” inside leaves and can cause early leaf drop in small plants; control them by regular checking, removing and destroying mined leaves early, keeping seedlings healthy with some shade, water and compost, and using a neem-based spray in nurseries if needed. Scale insects look like tiny bumps on twigs and under leaves and make leaves sticky ; reduce them by cutting and destroying heavily infested twigs, washing/wiping insects off young trees with plain water (or mild soap/ash water), and spraying neem on the underside of leaves and soft twigs.', NULL),
(10, 'Falcataria falcata', 'Ai‑bahe/Ai-Kafe', 'Falcataria refers to “falcate” (sickle-shaped), describing the leaflet shape, and falcata is Latin for “sickle-shaped/curved like a sickle,” again referring to the leaflets', 'Falcataria falcata grows best in the cooler highland areas of Timor-Leste (such as Dare, Aileu, and Ermera) and is commonly cultivated as a shade tree for coffee.', 'Falcataria falcata is a very fast-growing medium–large tree, often 24–30 m tall (can be taller), with a straight trunk and long clear stem; crown in open areas looks like an umbrella; leaves compound, feathery, with many small leaflets that are slightly curved, and the leaflets are in many pairs; flowers creamy white and small, like tiny bells; fruit a narrow flat pod about 10–13 cm long and ~2 cm wide, turning brown when dry and splitting open; seeds 15–20 in one pod, small (~6 mm), dull dark; The species can be identified from the tall straight trunk with umbrella-like crown, feathery leaves with many small curved leaflets, and narrow flat pods.', 'Pinnately compound (Double)', 'Pod', 'Flowering: March to June & October to December; Fruiting: May to August & December to February', 'Falcataria falcata produces thin, flat pods in loose clusters that turn from green to uniform pale/dark brown, becoming dry and papery; mature pods  release many small flat seeds. Collect pods just before they naturally split, preferably from the tree. In Timor-Leste, mature pods are typically available May–August and again December–February. Sun-dry pods briefly until they open, then extract seeds, shade-dry, and store in a cool airtight container. Seeds have hard-coat dormancy, so pre-treat by pouring boiling water over seeds and soaking as the water cools for 12–24 hours. Sow 0.5–1 cm deep in seedbeds or bags (2–3 per bag, thin later) using a topsoil:sawdust mix (1:1). With treatment, germination is very fast (often 80%+ within a week, sometimes in 1–2 days); provide light shade only at germination and move to full sun within 1–2 weeks, watering regularly but avoiding waterlogging.', 'Falcataria falcata (sengon/falcata) grows fast, but it can be infected by gall rust and stem borers, especially in dense, single-tree plantations, this can slow growth and may even kill young trees. Gall rust causes brown, rough “lumps” on shoots and branches, bending and bushy growth, and sometimes branch drying; reduce it by avoiding crowded pure blocks (mix with other crops/trees), planting only clean healthy seedlings, cutting and destroying galled twigs early, and removing badly infected trees. Stem borer attack shows as small holes with powdery sawdust and dying branches above the hole; manage it by good spacing, regular checking, killing the grub inside the hole with a wire and sealing the hole with clay + cow dung, and removing heavily attacked trees and destroying infested wood.', NULL),
(11, 'Canarium vulgare', 'Ai-Kiar', 'Canarium is from the Malay/Moluccan vernacular kanari/kenari, and vulgare is Latin for “common/usual,” possibly referring to its gregarious occurrence in habitat', 'Canarium vulgare grows occasionally along hilly streams, especially around Baguia and Liquica.', E'\nA tall tree up to about 45 m with butteressed root; leaves are compound, usually with 9–11 oval leaflets; flowers are small and separate as male and female, borne in clusters at the ends of branches; fruit is fleshy, oval and smooth, green when young and turning dark purple to black when ripe; inside the fruit is a hard stone with an inner kernel that is edible; The species can be identified from the 9–11 leaflet leaves and the smooth oval fruits that turn dark purple/black with an edible kernel inside.\n', 'Pinnately compound (single)', 'Drupe', 'Flowering: September to December; Fruiting: May to July', E'Canarium vulgare  produces smooth, ovoid drupes that ripen from green to dark purple/black, with soft flesh and a very hard stone enclosing the oily kernel. Collect mature fruits from May to July when fully dark and hardened, preferably picked from the tree or gathered regularly from the ground, discarding insect-damaged or mouldy fruits. Depulp and sun-dry the stones; dried stones can be stored for months (often up to ~1.5 years) with little loss of viability. Because the hard endocarp delays germination, pre-treat by soaking stones for 2 days, then gently crack or nick/file one end to let water in. Sow 3–5 cm deep in a well-draining medium (sand:soil:compost 1:1:1), ideally horizontally or with the cracked side slightly downward, under ~50% shade. Keep consistently moist but well drained. With cracking, germination may start in 6–8 weeks and continue over 2–3 months, while untreated stones can take 6–12 months. Maintain shade and airflow, then gradually harden to higher light; transplant at 6–9 months (about 20–30 cm tall) at the start of rains.\n', E'Canarium vulgare is usually hardy, but young plants, shoots and fruits can still get damaged and give slower growth or lower yield. Termites can hollow the base, and cause sudden wilting; reduce this by using strong seedlings, clearing old stumps/woody waste, keeping mulch away from the stem, and using well-rotted compost.\nA shoot-feeding bug can blacken shoot tips and damage flowers/fruits; manage it with good spacing, pruning and destroying damaged shoots, regular checking, hand-picking early, and keeping flowering plants nearby for helpful insects.\n\n', NULL),
(12, 'Casuarina equisetifolia', 'Ai-Kakeu', 'Casuarina comes from the Malay word kasuari (cassowary), referring to the tree’s needle-like branchlets that look like cassowary bird feathers, and equisetifolia is Latin for “horsetail-leaved,” describing its thin, jointed leaves similar to Equisetum (horsetail plants).', 'Casuarina equisetifolia grows abundantly across Timor-Leste, occurring naturally along coastal areas, and it also grows well in a wide range of soil types.', 'A medium–large tree often 10–30 m tall;  Leaves llook like thin green needle-like threads; bark grey-brown and rough; flowers very small and not showy, male flowers in thin spikes and female flowers as small buds; fruit looks like a small woody cone , green then brown, opening when dry; seeds very small and flat with a thin papery wing, carried by wind; The species can be identified from the needle-like green jointed branchlets and the small woody cone-like fruits.', 'Simple', 'Capsule', 'Flowering: September to October; Fruiting: February to June.', 'Casuarina equisetifolia produces small, woody cone-like fruits that mature from green to straw- or chestnut-brown and become dry and brittle as they ripen. Mature cones open naturally to release tiny, winged seeds and are best collected when they detach easily or fall after wind, usually between February–March and sometimes again around June–July. Collected cones should be sun-dried for a few days until the scales open and seeds are released. No pre-treatment is required. Sow seeds shallowly (about 0.5–1 cm) on a well-drained medium such as sand or a sand–soil mix, lightly covering and mulching to prevent wash-off. Germination begins within 5–10 days and is mostly complete by 2–3 weeks. Keep beds moist but not waterlogged, and maintain full sun. Prick out seedlings at 3–4 weeks into polybags, and transplant to the field at about 3–4 months when 15–20 cm tall.', E'The major pest is the bark-feeding caterpillar  that makes holes and tunnels in the trunk and branches, which can weaken the tree. A simple non-chemical method is mechanical control, find the tunnel opening and seal it with tar/wax-like material so the larva can’t continue. Infestation often rises after continuous rains and is usually lower in hotter, drier conditions, so planting in suitable sites and being extra alert after rainy periods helps reduce damage.\nCasuarina can also get mealybugs (small, white, cotton-like insects) that sit on young shoots and needles and suck plant sap. They often leave a sticky layer, which can later turn into black sooty fungus, and the tree may look weak, yellow and slow-growing. Control it by washing/wiping them off on small trees, cutting and destroying heavily infested twigs, and spraying neem oil/neem-based mix on the affected parts ; also keep the area clean and reduce ants, because ants protect these pests.\n', NULL),
(13, 'Pterocarpus indicus', 'Ai-na', 'Pterocarpus comes from Greek pteron (“wing”) + karpos (“fruit”), referring to its winged seed pods, and indicus is Latin for “of India/Indian,” pointing to its association with the Indian region in early botanical naming.', 'Pterocarpus indicus grows along hilly roadsides and is common across Timor-Leste.', E'An evergreen to semi-deciduous medium–large tree up to about 40 m, a spreading dome-shaped crown and drooping branches, bark slightly cracked and scaly; when cut it may ooze red sap; leaves alternate and compound, flowers in branched clusters from leaf joints and branch ends, bright yellow, fragrant, about 1.5 cm; fruit a round flat disc-like pod with a wide wing around the edge, green and slightly hairy when young, turning pale brown and smooth when ripe, and it does not split open; seeds 1–2 per pod, brown; The species can be identified from the yellow fragrant flowers and the small round winged disc-like pods.\n', 'Pinnately compound (single)', 'Pod', 'Flowering: August to September; Fruiting-May to June', 'Pterocarpus indicus produces distinctive round, winged pods (4–6 cm wide) that turn from green to straw-brown as they mature, becoming dry and papery with a hard central seed. In Timor-Leste, pods are usually collected during the dry season (around June–July) when they are fully brown and firm, preferably before they fall. The pods are indehiscent, so seeds remain enclosed; trimming or partially cutting the wing helps improve soil contact and moisture absorption. Sow whole pods on the soil surface, pressing them lightly into a well-drained sandy or sandy-loam medium and covering very lightly. Keep the bed moist but not waterlogged. Germination typically begins within 3–4 days under warm conditions. Provide light shade and good airflow, and weed regularly. Once seedlings develop several true leaves, transplant into polybags and gradually harden before field planting at 15–20 cm height.', 'Pterocarpus indicus can be badly affected by wilting disease, where leaves turn yellow, branches dry back, and whole trees may die, and it can also get leaf miners and wood borers that make leaves deformed or weaken the stem. A good strategy is to plant only healthy seedlings, keep good spacing and mixed planting, and avoid hurting the bark during weeding or pruning. ', NULL),
(14, 'Delonix regia', 'Ai‑kesi/Madre‑Kakau/Samatuku Malae', 'Delonix comes from Greek delos (“clear/visible”) + onyx (“claw”), referring to its showy, claw-like petals, and regia is Latin for “royal,” describing its grand, flamboyant flowers.', 'Delonix regia is commonly planted along roadsides and is widely seen across the country.', 'A deciduous to semi-evergreen medium-sized tree, with a very wide umbrella-like spreading crown and heavy shade, trunk often short with low spreading branches, bark greyish-brown and fairly smooth to slightly cracked; Leaves large, feathery, fern-like double compound leaves made of many tiny leaflets; Flowers large, very showy, bright red to orange-red, often with one petal marked with yellow/white; Fruit long, flat, hard woody pods hanging down, turning dark brown when ripe, usually 30–60 cm long; Seeds hard, oval brown seeds arranged in a row inside the pod; The species can be identified from its fern-like leaves, bright red-orange flowers, and long hanging woody pods.', 'Pinnately compound (Double)', 'Pod', 'Flowering: April to May; Fruiting: October to December', 'Delonix regia produces long, woody pods (30–60 cm) that turn dark brown and hard when mature, usually from May to July. Mature pods should be collected directly from the tree once fully dry, then sun-dried further and split open to extract the flat, hard seeds. The seeds have a very tough coat, so scarification is essential—either by filing the seed coat or soaking in hot water until swollen. Sow scarified seeds 0.5–1 cm deep in sandy or sandy-loam soil, spacing lightly if in beds. Germination is rapid once treated, with roots emerging in 4–7 days and most seeds sprouting within two weeks. Provide light shade initially and keep soil moist but well-drained. Seedlings grow quickly and can be transplanted at 3–4 weeks when about 10–15 cm tall, gradually hardening them to full sun.', 'The species often gets infected with root rot, especially in places with heavy rainfall, which slowly damages the roots and weakens the whole tree. It is also attacked by small beetles and their young, which drill into the seed pods and make holes so the seeds spill out. Sometimes shoot-boring insects damage the tender new growth, reducing healthy branching. In a few cases, leaf-eating caterpillars/insects can strip off most or even all of the leaves.', NULL),
(15, 'Tamarindus indica', 'Ai‑sukaer', 'Tamarindus comes from the Arabic phrase tamr e hind meaning “Indian date,” referring to its date-like pulp, and indicus is Latin for “of India/Indian,” pointing to its long association with India in early naming.', 'Tamarindus indica is common and abundant, especially around villages.', 'A long-lived evergreen to semi-deciduous medium–large tree, with a thick trunk and a broad, rounded, spreading crown that gives deep shade; Leaves small, soft-looking single compound leaves with many pairs of tiny leaflets, giving a fine feathery look; Flowers small, in short clusters, pale yellow to cream with fine red/orange streaks, not very showy; Fruit thick, curved to straight brown pods, dry and slightly brittle when ripe, with a sticky sweet-sour pulp inside; Seeds hard, smooth, glossy dark brown seeds packed inside the pulp; The species can be identified from the dense shady crown, fine feathery leaves, and the brown pods with sticky sweet-sour edible pulp.', 'Pinnately compound (single)', 'Pod', 'Flowering: June to July; Fruiting:March April', 'Tamarindus indica produces elongated, brittle pods that turn brown and dry when mature, enclosing several hard, glossy seeds in a sticky pulp. In Timor-Leste, fruits usually mature from June to September and are best collected directly from the tree when fully brown to avoid insect or moisture damage. After collection, remove the pulp, clean the seeds, and shade-dry before storage. Tamarind seeds have a hard coat and require pre-treatment for good germination; soaking in hot water (about 80 °C) and leaving to cool for 12–24 hours, or lightly nicking the seed coat, greatly improves results. Sow seeds about 1 cm deep in well-drained sandy or loamy soil, either in polybags or nursery beds. Germination usually begins within 5–10 days and is mostly complete in 2–3 weeks. Provide light shade initially, then gradually expose seedlings to full sun. Seedlings grow quickly and are ready for transplanting at about 3 months of age.', 'Tamarind trees can be badly affected by tiny sap-sucking insects (like scales and mealybugs) and by insects that bore into pods, seeds, or branches, which can reduce the amount of good fruit you can sell. Different places report different problems—some areas see pod-eating beetles, termites, or pests that attack stored tamarind after harvest. In certain seasons, fruit borers can become a major issue and sharply cut marketable yield. Tamarind can also face several plant diseases that show up as leaf marks or white powder on leaves, black mouldy coating, and rotting or damaged stems, roots, wood, or bark.', NULL),
(16, 'Eucalyptus urophylla', 'Ai‑ru', 'Eucalyptus comes from Greek eu (“well”) + kalyptos (“covered”), referring to the flower bud being capped, and urophylla comes from Greek oura (“tail”) + phyllon (“leaf”), meaning “tail-leaved,” describing its tapering leaf shape.', 'Eucalyptus urophylla is occasionally found in high-altitude hilly roadsides and mountain areas, especially around Dare, Aileu, Ermera, and Baguia.', 'A tall evergreen tree that can grow about 45–55 m, usually with a straight trunk; bark usually persistent, fairly smooth and slightly fibrous, reddish-brown to brown with shallow lengthwise cracks, sometimes rougher near the base; Young leaves mostly in opposite pairs, broad and lance-shaped; adult leaves long, narrow-lance shaped, held alternately to near-opposite; Flowers small, in little clusters from the leaf joints; Fruit small, dry woody capsules, cup-shaped to cone-like; Seeds very small, black, and slightly curved/half-moon shaped; Eucalyptus urophylla can be identified from E. alba from its generally taller, straighter habit, its usual occurrence above about 500 m altitude, and its reddish-brown bark (often with shallow lengthwise fissures) instead of the smooth white/cream powdery bark of E. alba.', 'Simple', 'Capsule', 'Flowering: December to January; Fruiting: April to May; ', 'Eucalyptus urphylls produce small, capsule-borne seeds that are released when mature capsules dry and open. Seeds are collected from fully developed capsules, dried, and cleaned before storage or sowing. For improved germination, seeds benefit from cold stratification by keeping them moist and refrigerated for 4–6 weeks, which helps break physiological dormancy. After treatment, seeds are surface-sown on a fine, well-drained medium such as soil and sand, and lightly pressed without covering. Germination occurs best at 20–25 °C under gentle light and good ventilation, usually within 2–3 weeks. Seedlings are transplanted into polybags after 30 days once they develop 2–4 true leaves. Young plants prefer full sun and well-drained, slightly acidic soil. With good care, Eucalyptus grows rapidly, often reaching several metres in height within the first year', 'Amblypelta and Amorbus are bug-like pests that harm eucalyptus by piercing young shoots and drinking the plant’s sap. In very young trees, this can make the shoot tips wilt and die back, sometimes killing the main top shoot and leaving the tree looking bushy or hedge-like. Natural control options are not well studied, but neem oil and growing other crops alongside (intercropping) are sometimes suggested.', NULL),
(17, 'Eucalyptus alba', 'Ai‑bubur', 'Eucalyptus comes from Greek eu (“well”) + kalyptos (“covered”), referring to the bud’s cap, and alba is Latin for “white,” referring to the tree’s pale/whitish bark.', E'Eucalyptus alba grows abundantly on low-altitude coastal hills, especially along the Dili–Baucau corridor.\n', 'A small to medium tree usually about 5–18 m tall, with a spreading crown about 5–15 m wide, trunk often bent; bark smooth, powdery, and pinkish-red to white or cream-coloured, often looking pale from a distance; Leaves on young plants alternate, broad and egg-shaped to almost round, fairly large; adult leaves egg-shaped to lance-shaped, smaller than juvenile leaves; Flowers buds in clusters of seven on short stalks, flowers white; Fruit small, woody capsules, cone-shaped to half-round; Seeds small and typical of eucalypts; The species can be identified from its shorter height, bent trunk, and pale white/cream powdery bark with clusters of white flowers.', 'Simple', 'Capsule', 'Flowering: December to January; Fruiting: April to May; ', 'Eucalyptus alba produces very small, dust-like seeds enclosed in tiny woody capsules that develop in clusters along the branches. As the capsules mature, they change from green to light brown and become dry and firm. Seed collection should be done directly from the tree just before the capsules split open naturally, as once they open the fine seeds are easily lost. Collected capsules can be sun-dried in a tray or box for a few days until they release the seeds, which can then be cleaned and stored dry. For germination, no pre-treatment is required. Seeds should be lightly broadcast on the surface of a fine, well-drained medium such as sand or a sand–soil mix and gently pressed in without covering. Maintain light moisture and good airflow. Germination usually begins within 7–14 days under warm conditions.', 'Amblypelta and Amorbus are bug-like pests that harm eucalyptus by piercing young shoots and drinking the plant’s sap. In very young trees, this can make the shoot tips wilt and die back, sometimes killing the main top shoot and leaving the tree looking bushy or hedge-like. Natural control options are not well studied, but neem oil and growing other crops alongside (intercropping) are sometimes suggested.', NULL),
(18, 'Parkia speciosa', 'Petai‑cina/Pete/Petai', 'Parkia commemorates the Scottish explorer Mungo Park, and speciosa is Latin for “showy” or “beautiful,” referring to the plant’s striking flowers.', E'Parkia speciosa is not common and is mainly found as a cultivated household tree in higher-altitude villages, especially around Dare, Aileu, and Ermera.\n', 'A medium–large tree about 15–40 m tall, with young twigs often slightly hairy; Leaves large, feathery, double compound leaves with many pairs of small narrow leaflets; Flowers cream-white, or yellowish-white, packed tightly into showy dense heads; Fruit large pods about 35–55 cm long, straight or more commonly twisted, hanging in small bundles, green when young and turning black when ripe, each pod holding about 10–18 big seeds; Seeds large,and the seeds are edible and commonly eaten as a vegetable (noted for a garlic-like taste and very strong smell); The species can be identified from the feathery leaves and the long twisted pods hanging in bunches with large edible seeds inside. ', 'Pinnately compound (Double)', 'Pod', 'Flowering: May to June; Fruiting: August to September', 'Parkia speciosa (petai/stink bean) seeds come from long pods that contain several large seeds. For best results, collect mature pods directly from the tree when they are fully developed to avoid insect damage and fungal problems, then open the pods to extract the seeds soon after harvest. Seeds have a hard seed coat that can delay germination, so many growers remove the seed coat or nick the seed near the micropyle to help water enter and speed up sprouting. Soaking seeds in water before sowing also helps improve germination uniformity. Seeds are sown on the surface of a well-drained mix such as sandy soil or sand–soil blend and pressed lightly without deep covering, as light contact with moisture encourages sprouting. Under good conditions, treated seeds typically begin to germinate within about 10–15 days, and uniform germination and vigorous seedling growth follow with adequate moisture and light', 'Parkia speciosa can be damaged by wood-boring insects and fungi that stain or spoil the wood, and the softer outer wood is especially easy for borers to attack. In some areas, moth larvae can also spoil the seeds. Fruits, flowers, buds, and bark may be eaten by animals and birds like hornbills, monkeys, and squirrels. Management includes keeping wood dry and well-protected after cutting, removing badly attacked parts early, and using simple physical protection like fencing or guards where wildlife damage is common.', NULL),
(19, 'Terminalia catappa', 'Ai‑Kalesi/Ketapang/Ai‑lese', 'Terminalia refers to the leaves clustering at the “ends” of branches (from Latin terminalis), and catappa comes from the local/common name katappa used in parts of South and Southeast Asia for this tree.', E'Terminalia catappa commonly grows in coastal areas.\n', 'A large deciduous to semi-evergreen tree, with a very distinctive layered, pagoda-like crow; Leaves very large, broad, and leathery, clustered near the ends of branchlets, turning yellow to orange-red before falling; Flowers small, greenish-white, in slender spike-like clusters from the leaf joints, not showy; Fruit oval to almond-shaped, slightly flattened and smooth, green when young, turning yellow, red or purple as it ripens, with a fibrous outer layer; Seeds a hard “stone” inside the fruit containing an edible kernel (often called tropical almond); The species can be identified from the flat tiered “pagoda” branching, very large leaves that redden before shedding, and the almond-like fruits with an edible kernel.', 'Simple', 'Drupe', 'Flowering: May to June; Fruiting: April to June', 'Terminalia catappa produces ovoid drupes that turn from green to yellow or reddish-brown when mature, enclosing a hard, woody stone with the seed inside. Mature fruits are best collected between April and June, preferably picked directly from the tree or gathered fresh from the ground. After collection, the fleshy outer layer should be removed and the nuts washed and shade-dried. Because the hard endocarp delays germination, lightly cracking the shell or soaking the fruit overnight greatly improves results. Seeds are sown about 2 cm deep in a well-drained sand or sandy-loam medium, preferably laid flat. Keep the medium moist but not waterlogged. Germination usually begins within 3–8 weeks, faster when the shell is cracked. Seedlings grow a strong taproot, so early transplanting into deep containers is recommended. Light shade and regular watering support healthy early growth.', 'Terminalia catappa is usually get pest problems when it is young, mainly from leaf-eating insects that can remove a lot of leaves. Another common issue is tiny insects called thrips that damage leaves, make them look bronze or scorched, and can cause early leaf drop. The best strategy is regular checking, removing pests by hand on small trees, and cutting off and safely destroying badly affected leaves and shoots. ', NULL),
(20, 'Peltophorum pterocarpum', 'Ai‑silose/Ai‑mame', 'Peltophorum comes from Greek peltē (“small shield”) + phoros (“bearing”), referring to its shield-like pods, and pterocarpum comes from Greek pteron (“wing”) + karpos (“fruit”), meaning “winged-fruit.”', E'Peltophorum pterocarpum grows along hilly roadsides.\n', 'A fast-growing evergreen to semi-deciduous medium–large tree , with a broad rounded crown and spreading branches, bark grey-brown and rough with cracks as it ages; Leaves large, feathery, double compound leaves with many small leaflets giving a soft fern-like look; Flowers bright golden-yellow, slightly fragrant, borne in big upright branched clusters at the ends of branches, often making the whole crown look yellow when in bloom; Fruit flat, thin, woody pods, oval to oblong, reddish-brown to dark brown when ripe, usually not splitting open; Seeds 1–4 seeds per pod, hard and brown; The species can be identified from the large golden-yellow flower clusters and the flat reddish-brown woody pods along with the feathery double compound leaves.', 'Pinnately compound (Double)', 'Pod', 'Flowering: April to May; Fruiting: April to June', E'Peltophorum pterocarpum produces flat, woody pods that turn from coppery red to dark brown or black when mature. Each pod contains 1–4 hard, flattened seeds. Mature pods are collected from the tree between April and June, dried until they split easily, and the seeds are cleaned. Because the seeds have a very hard coat, pre-treatment is essential: soaking in room-temperature water for 24 hours or briefly in hot water greatly improves germination. Sow seeds about 1 cm deep in a well-drained sand and soil mix, lightly covering them. Germination usually begins within 1–2 weeks when treated properly. Provide light shade during early growth, then gradually expose seedlings to full sun. Maintain regular watering without waterlogging. Seedlings grow quickly and can be transplanted after 4–6 weeks when about 10 cm tall.\n', E'Peltophorum pterocarpum is usually  hardy, and most problems are only occasional leaf-eating insects. Bagworms can be spotted by the tiny “bags” hanging from leaves and twigs, and they slowly thin the canopy by eating leaves. Looper caterpillars can strip leaflets and make the crown look thin or nearly leafless during outbreaks, especially on young trees. The simple strategy is to keep trees strong, check them regularly, encourage birds and helpful insects, and hand-pick or prune and destroy heavily infested parts when the problem is small.\n', NULL),
(21, 'Santalum album', 'Ai‑kameli', 'Santalum comes from the Arabic–Persian word sandal (sandalwood), and album is Latin for “white,” referring to its pale wood (especially the sapwood).', 'In Timor-Leste, Santalum album grows naturally in dry monsoon forests/scrub, best on well-drained sandy or stony soils', E'A small to medium evergreen tree, usually with a slender trunk and a rounded crown, bark grey to dark brown and rough with age; the heartwood is highly fragrant ; Leaves simple, opposite, smooth and leathery, medium green and slightly shiny; Flowers small, in short clusters from the leaf joints, greenish to creamy when young and often turning reddish-brown or purplish as they age, mildly fragrant; Fruit a small round to oval fleshy drupe, green when young and turning purplish-black when ripe; Seeds usually one hard seed inside each fruit; The species can be identified from the opposite smooth leaves, small clusters of flowers that darken with age, the small blackish fruits, and the strong sandalwood fragrance from the wood.\n\n', 'Simple', 'Drupe', 'Flowering: Nov to Dec; Fruiting: March to June', 'Sandalwood produces small, hard seeds enclosed in a fleshy purple-black fruit that matures during the dry season. Mature fruits are collected directly from the tree, cleaned to remove pulp, and air-dried before sowing. Seeds germinate best in a well-drained medium such as sand or sandy soil, kept moist but not waterlogged. Germination usually begins within 2–4 weeks under warm, shaded conditions. Sandalwood is a semi-parasitic species and requires a suitable host plant from the early seedling stage to supply nutrients through haustorial connections. Fast-growing herbs or shrubs like Alternanthera, Cajanus etc  are commonly used as primary hosts. Seedlings should be grown under partial shade, with careful watering, until well established before field planting with suitable long-term host species.', E'Santalum album can be badly affected by “spike disease,” which spreads through root contact and can kill trees within 1–2 years after symptoms start, and flowers may stop setting fruit. Because there is no reliable cure once a tree is infected, the best strategy is prevention: keep good spacing (about 5–6 m) and avoid planting too close together. Grow sandalwood with suitable companion/host trees like Casuarina, Acacia, or Eucalyptus, while keeping host plants healthy with good weeding and shade for seedlings. Also reduce sap-sucking insects that may help spread the disease by using simple netting/cloth protection, especially on young plants.\n', NULL),
(22, 'Swietenia macrophylla', 'Ai‑mahony', 'Swietenia names after Gerard (von) van Swieten, a Dutch-Austrian physician and botanist, and macrophylla comes from the Greek makros (“large”) + phyllon (“leaf”), referring to the tree’s large leaves/leaflets.', 'Swietenia macrophylla is a popular, non-native tree in Timor-Leste, widely cultivated across many areas for its valuable timber.', 'A large, fast-growing deciduous to semi-evergreen tree, usually with a tall straight trunk and a broad rounded crown, bark grey-brown and becoming rough and fissured with age; the timber is hard and durable, typically reddish-brown; Leaves compound (pinnate) and alternate, with several pairs of large, smooth, glossy, oval to lance-shaped leaflets; Flowers small and greenish-white to creamy, borne in loose branching clusters (panicles), usually mildly fragrant; Fruit a large, hard, woody capsule that turns brown and splits open into several valves when mature; Seeds numerous, flat and papery with a long wing for wind dispersal; The species can be identified from the large pinnate leaves with glossy leaflets, the big woody capsules that split open, and the many winged seeds.', 'Pinnately compound (single)', 'Capsule', 'Flowering: July to September; Fruiting: December to February', 'Collect seeds from mature mahogany trees (about 30–40 years old), ideally just before the rainy season, and sow them soon after collection for best results. After sun-drying, seeds can be stored airtight and stay viable for more than six months. Sow seeds without pre-treatment, placing them shallowly (about 0.5–1 cm) in a well-drained nursery mix (e.g., wood chips, coco husk, crushed fruit shells) under filtered light. Germination usually happens within 2–3 weeks, and seedlings are ready to transplant when they reach about 15–20 cm tall.', 'The main pest of mahogany is the mahogany shoot borer (Hypsipyla robusta), whose larvae bore into the tender top shoots and cause dieback. This stops the tree from growing straight, leading to stunted growth and a bushy, multi-stem form. Attacks are usually worse in monoculture plantations and warm, humid conditions (around 25–30°C). Reduce risk by mixing species (intercropping with trap trees like Toona ciliata or Pterocarpus indicus), removing infested shoots/larvae, and planting in lower altitudes below 500 m. Prevent root rot by keeping soil well-drained, avoiding waterlogging, and giving seedlings enough sunlight.', NULL);
INSERT INTO public.species_tet (species_id, scientific_name, common_name, etymology, habitat, identification_character, leaf_type, fruit_type, phenology, seed_germination, pest, definition) VALUES
(1, 'Aleurites moluccana', 'Ai-Kami', 'Aleurites mai hosi lian Gregu aleuron ne''ebé signifika "ai-farina/farina", refere ba revestimentu ho ai-farina, no moluccana signifika "husi Molukas (Illa Maluku, Indonézia)', 'Komún husi tasi-ibun to’o foho klaran iha Timor-Leste, moris iha ai-laran sekundáriu, ninin mota no iha estrada ninin foho-lolon ne’ebé nakloke.', 'Ai-hun ida ne''ebé boot-médiu; fulin sira alternadu, boot, simples no dala barak ho lóbulo 3 (liuliu iha musan sira ne''ebé sei ki''ik), parte okos kór-mutin/osan-mutin; ai-funan nia tahan naruk tebes; sap hanesan susu-been; ai-funan mutin iha ramu sira; ai-fuan ho kulit toos ~4-6 cm, verde bainhira sei ki''ik, sai kór-kafé-metan bainhira tasak, ho "candlenuts" 1-2 ne''ebé iha mina.', 'Simples', 'Drupes', 'Iha Tinan tomak', 'Halibur ai-fuan maduru kór-kafe husi ai-horis ka endokarpu maran. Hasai fini hodi halo mamar ai-fuan fresku sira loron balun, hasai kulit, fase, no maran; soe ai-horis sira ne''ebé namlele iha bee no rai fini maran sira durante fulan barak ho umidade ~10-12%. Tanba endokarpu ne''e toos tebes, maran kulit sira iha loro-matan durante loron 2-3 no hafoin hatama kulit manas sira ba bee (xoke termál) hodi rahun sira; proteje fini sira hosi roedor sira. Uza meiu jerminasaun ida ho maizumenus 2:1 rai-leten ba rai-henek mota nian, no kuda ai-horis ne''ebé rahun ho klean 2-3 cm iha polybags klean ka iha kama ne''ebé klean no klean (abut boot). Ho rahun, jerminasaun normalmente akontese iha semana ~3-8 (balun iha semana 3-4) no taxa sira bele liu 80%, enkuantu fini sira ne''ebé la hetan tratamentu bele lori fulan 3-4 no dala barak dodok.', 'Ba candlenut, ameasa viveiru nian ne''ebé imediatu liu maka roedor sira ne''ebé dada ba musan sira ne''ebé iha mina - proteje kama jerminasaun nian no bandeja sira ho arame ka rede ne''ebé di''ak no mantein andár sira moos. Iha to''os, moras fungal sira kauza defoliasaun no ai-fuan monu prematuru, enkuantu borers stem horn no termites subterráneu estraga tahan, kola, no abut. Ai-fuan sira hetan ataka beibeik hosi susuk ai-fuan nian no susuk fini/pod borers; kolesaun no destruisaun regulár ba ai-fuan sira ne''ebé monu ka infestadu maka esensiál.', NULL),
(2, 'Tectona grandis', 'Ai-Teka', 'Tectona mai hosi lian Gregu téktōn "karpinteiru/konstrutór", ne''ebé fó hanoin katak uza hanesan ai, no grandis maka lian Latin ba boot/boot.', 'Barak liu kuda no dalaruma naturaliza iha foho maran no foho kalkáriu', 'Ai-hun boot ida, ne''ebé monu; fulin sira boot tebes, kontráriu no simples; soe nia fulin sira durante fulan 3-4 iha tempu maran nia rohan; ai-funan ki''ik (≈8 mm), kór-kafe to''o mutin, iha ulun boot ho sanak; ai-fuan ida ne''ebé redonda, toos, ai-tahan ho kuartu haat, taka iha "bexiga" ne''ebé maka''as, hanesan surat-tahan, verde-mutin no kór-kafé bainhira sai tasak.', 'Simples', 'Drupes', 'Fuan: Juñu to''o Setembru; Frutasaun: Novembru to''o Janeiru', 'Halibur ai-fuan sira ne''ebé tasak no maran; hasai sépalu/kálix sira iha liur, hafoin eskarifika uitoan kulit ne''ebé toos ho lija ka fatuk ne''ebé maka''as. Enxe polybags ho mistura rai no kompos ne''ebé drenajen di''ak iha proporsaun 3:1. Kuda fini 3-5 kada saku ho klean 1-2 cm ka kuda uluk iha kama jerminasaun nian.', 'Termite sira maka problema prinsipál ba ai-teka; sira han iha ai-laran, husik hela ai-tahan mamuk no rai-henek- bainhira hetan ataka maka''as, tesi no sunu maka opsaun prátika úniku. Lagarta sira ne''ebé han ai-funan bele hasai ai-funan lalais; halo inspesaun beibeik, mantein koroa sira nakloke ho poda kmaan, no hasai ai-funan/sanak sira ne''ebé infestadu maka''as. Ai-tahan sira halo kuak redonda ki''ik sira no dudu sai pó hanesan serru; evita atu hakanek ai-horis sira no hasai/estraga ai-horis ne''ebé hetan infestasaun. Iha viveiru sira no ai-horis sira ne''ebé sei ki''ik, mohu derepente dala barak mosu tuir drenajen ne''ebé ladi''ak ka manejamentu abut ne''ebé maka''as - uza kama sira ne''ebé iha drenajen di''ak, rega ho hanesan, no tesi sai musan sira ne''ebé kanek/mate iha sintoma ikus nia okos.', NULL),
(3, 'Toona ciliata', 'Ai-Saria', 'Toona mai hosi naran vernakular indianu "toon/tun" ba ai-hun, no ciliata maka latinu ba "fringed/hairy", refere ba fulun ki''ik sira iha parte sira hanesan ai-funan nia ninin', 'nia moris iha mota no rai-kuak sira ne''ebé úmidu iha rai-bokur ne''ebé iha drenajen di''ak hosi besik tasi-ibun to''o besik 1,500 m', 'Ai-hun ida ne''ebé aas no monu;  ai-tahan dala barak iha apoiu, kulit liur kór-kafé nakukun, áspera no eskaladu;  fulin sira alternadu no pinnadu mesak ho 4-8 par opostu ba sub-opostu hosi fulin lanceoladu sira, fulin foun kór-roza nabilan; ai-funan ki''ik, mutin no morin, iha spray terminal ne''ebé naruk no monu; ai-fuan kapsula maran ho válvula 5 ne''ebé fahe hosi leten hodi hasai fini ki''ik barak, ho liras.', 'Kompostu pinnadu (ida de''it)', 'Kápsula', 'Fuan: Marsu - Maiu; Frutasaun: Jullu - Agostu', 'Halibur ai-fuan sira ne''ebé tasak no tasak tomak hosi ai-hun bainhira ai-fuan sira hahú fahe. Enxe viveiru sira ho mistura rai-leten ne''ebé drenajen di''ak no mós kompos ka rai-henek. Kuda iha superfísie ka taka ho kmaan tebes iha liña sira ho distánsia 10 cm;', 'Toon joven (Toona ciliata) dala barak sofre husi ai-sanak ne''ebé hamate ai-sanak leten no hamosu garfu no koroa ne''ebé kro''at; verifika beibeik pontu sira, mantein líder ida ne''ebé loos, no tesi-no-sunu musan sira ne''ebé infestadu. Termite sira no besouro powderpost ataka ai, husik hela kuak ki''ik no rai-rahun hanesan ai-farina - evita kanek, hadook ai hosi rai, no hasai pedasuk sira ne''ebé infestadu maka''as. Mistletoe parazita mosu hanesan ai-horis verde iha sanak sira; tesi fali sanak ne''e ba ai ne''ebé saudavel no estraga ai-sanak sira. Abut no kotuk-laran dodok halo ai-horis sira sai fraku (daun sira sai mean, tahan sira ne''ebé nakloke, fungo sira ne''ebé hanesan prateleira iha baze); mantein ai-tahan nia hun maran no la kanek, no hasai ai-hun sira ne''ebé dodok ona. Proteje ai-oan no ai-oan sira hosi karau ho guarda simples ka moru to''o sira estabelese ho di''ak.', NULL),
(4, 'Sterculia foetida', 'Ai-nitas', 'Sterculia mai hosi lian Latin Sterculius, maromak estrume Romanu nian (stercus = estrume), no foetida maka lian Latin ba "morin aat/fétiku.', 'Ai-hun ida iha rai-tetuk ho rai-tetuk tasi-ibun ne''ebé manas no maran no fatuk-lolon sira, dala barak besik aldeia sira no iha estrada sira nia sorin.', 'Ai-hun ida ne''ebé boot, loos, no monu; kulit ne''ebé mos no kinur; ai-funan sira ne''ebé nakonu iha ai-sanak nia rohan, ho ai-funan 7-9, petíolu naruk (to''o ~20 cm) no ai-funan ho morin ne''ebé ladún di''ak; ai-funan iha sanak barak, kór verde to''o kór-roxu ne''ebé mamuk, ho mane no feto iha ai-hun ketak; ai-fuan lubun ida ho folikulu mean ne''ebé mahar ne''ebé sai hanesan ai-hun, ida-idak iha fini oioin ho kór ardózia, oblongu (~1.5–1.8 cm) ho aril mean ki''ik ida.', 'Kompostu palmadu', 'Folíkulu', 'Fuan: Fevereiru to''o Marsu, Fuan: Janeiru to''o Fevereiru. Ai-fuan sira tasak besik fulan 11 hafoin ai-funan sira mosu ba dala uluk.', 'Halibur ai-fuan mean ne''ebé tasak ona no fahe ai-fuan sira hodi hasai fini metan sira, hasai fini sira no fase pulpa hotu atu evita fungo. Tau fini sira iha bee laran durante oras 24, hafoin hasai kulit metan ne''ebé mihis ka hamoos uitoan. Kuda iha kama jerminasaun ho mistura rai-metan no adubu ne''ebé drenajen di''ak iha proporsaun 3:1. Tau fini iha nia sorin ka kuda ida-ne''e atu nune''e nia rohan ne''ebé maka rahun/rahun sai hanesan ka aas liu uitoan hosi superfísie.', 'Iha viveiru sira husi Sterculia foetida, problema prinsipál maka lagarta ne''ebé maka bele kona 70-80% husi ai-oan sira no kauza taxa mate ne''ebé aas tebes. Larva sira kose ai-funan ho seda ne''ebé di''ak, rola, no han iha laran, husik hela fatin "janela" ne''ebé mihis entre vena sira molok muda ba ai-funan foun. Verifika kama sira loroloron no hasai ka estraga ai-funan sira ne''ebé namlele ho lalar iha laran. Proteje kama jerminasaun nian ho rede insetu nian ne''ebé di''ak, mantein espasu no fluxu ar nian ne''ebé di''ak, no evita kreximentu ne''ebé buras liu no ho mahon. Iha sinál dahuluk sira, spray biolójiku hanesan spray neem (azadirachtin) bele ajuda hamenus estragu.', NULL),
(5, 'Albizia lebbeck', 'Ai-Samatuku', 'Albizia fó onra ba Filippo degli Albizzi, ne''ebé maka introdús Albizia ida ba Europa, no lebbeck mai hosi naran lokál Árabe/Índiku "lebbek/labakh', 'Espésie ne''e moris iha estrada ninin ne''ebé foho iha elevasaun ki''ik to''o médiu.', 'Ai-hun ida ne''ebé boot médiu, no monu; kulit kinur, fissuradu no kortizadu, fulin ho pinnadu duplu ho pinnae par 2-4, ida-idak iha fulin ki''ik barak ne''ebé obliku no obliku (~1.5–6.5 × 0.5–3.5 cm); ai-funan sira iha ulun esfériku boot, morin, mamar, kór-mean-verde iha tahan naruk sira; ai-fuan naruk, lahan, ho kulit hanesan surat-tahan, ho kór-kafé ne''ebé mutin, book an iha fini nia leten no la metin.', 'Kompostu pinnadu (duplu)', 'Pod', 'Fuan: Setembru-Novembru; Frutasaun: Maiu–Jullu', 'Halibur vagem sira bainhira sira maran, kór-kafé, no molok sira fahe; maran iha loro-matan loron balun atu nune''e sira loke, hafoin hamoos no rai fini sira maran. Pre-tratamentu hodi fakar bee ne''ebé foin tunu iha fini sira no rega durante oras 12-24 hodi halo mamar fulun ne''ebé toos. Enxe kama jerminasaun nian ho Rai: Rai-henek: Adubu iha mistura 1:1:1. Kuda ~1 cm klean; iha kama sira espasu fini sira ~5 cm iha liña sira, jerminasaun normalmente hahú iha semana 1-2 ho fini fresku, ne''ebé trata ona.', 'Iha viveiru sira, ai-oan Albizia nian dalabarak mate tanba damping-off no abut dodok sira seluk; uza media ne''ebé moos, ho drenajen di''ak, evita rega demais, no soe ai-horis sira ne''ebé moras sedu. Iha to''os, moras mohu ne''ebé maka''as bele trava bee nia suli, hodi hamosu mean iha ai-funan sira, mate derrepente, no mate hosi sanak sira ka ai-hun tomak; hasai ai-hun sira ne''ebé afetadu maka''as no evita atu hakanek abut no tahan sira.', NULL),
(6, 'Azadirachta indica', 'Kampu Sumaer', 'Azadirachta mai husi azad-darakht Pérsia nian ne’ebé signifika “ai-hun livre” (nobre ka la sujeita ba poda), no indica denota “husi Índia .', 'Espésie ne’e moris iha rai-maran no baibain kuda iha estrada ninin.', 'Azadirachta indica hanesan ai-hun ida ne’ebé médiu to’o luan, ho koroa ida ne’ebé arredondadu densu no kinur metan, kulit fissuradu. Daun sira ne’e kompostu trinadu, naruk 20–40 cm, Flores ki’ik, mutin to’o mean pálidu, morin, no lori iha sanak. Ai-fuan ne’e hanesan drope elipsoidal ho fini 1, verde-mean to’o kór-roxu bainhira tasak. Ai-hun ne’e hahú fó fuan hafoin tinan 5 no bele moris to’o tinan 200.', 'Kompostu ho pina (Single)', 'Droga', 'Flores: Janeiru–Marsu; Ai-fuan: Maiu–Agostu', 'Ai-fuan neem sira rekolla bainhira sira sai mean no mamar uitoan, di’ak liu kolleita diretamente husi ai-hun. Hafoin depulping no hamoos, fini sira tenke kuda fresku, tanba lakon viabilidade lalais no la presiza scarifikasaun. Rai ida:sand:Kompost mix husi 2:1:2 fornese meiu di’ak liu, ho fini ne’ebé kuda 1–2 cm iha polibag nia kle’an ka kama ne’ebé hasa’e. Jerminasaun baibain hahú iha loron 4–10 nia laran no barak liu kompletu iha semana 3–5. Fini fresku iha taxa susesu aas liu, enkuantu fini tuan hatudu jerminasaun ne’ebé redús.', 'Ai-neem baibain rezistente, maibé peste no moras balun afeta duni sira. Iha viveiru, ai-oan dala barak sofre tanba amortesimentu (kauza husi fungi) no fatin ai-funan husi fungi no baktéria oioin. Abut dodok no moras kór-roza bele estraga ai-hun sira ne’ebé idade boot liu, hodi hamosu ai-sanak mate.', NULL),
(7, 'Acacia mangium', '', 'Acacia mai husi akis Gregu (“pontu/barb”), refere ba espinha/tarak iha grupu, no mangium mai husi naran komun Molucan ne’ebé uza ba ai-hun ne’e.', 'Espésie ne’e moris di’ak liu iha rai sira ne’ebé degrada no adekuadu ba reabilitasaun rai, maske la’ós komún tebes ho natural.', 'Ai-hun ida ne’ebé buras lalais médiu–boot ho koroa luan; ai-funan alternadu no boot, espessura daun, verde nakukun ho venas paralelu 3–5 ne’ebé forte; kulit kulit to’o kór-kafé nakukun no áspera iha ai-hun sira ne’ebé idade boot liu; ai-funan kreme ki’ik–mean pálidu iha spike mihis naruk; ai-fuan naruk ida ne’ebé latan ~7–15 cm, verde depois kór-kafé nakukun/metan, dala barak torta bainhira maran no fahe nakloke; fini barak, ki’ik ne’ebé nabilan metin metan, dala barak ho ponta ki’ik laranja/mean;', 'Simples', 'Fó', 'Flores: Jullu to’o Agostu; Frutador: Dezembru to’o Fevereiru 2019.', 'Acacia vagem sira rekolla bainhira maran tomak, kór-kafé nakukun to’o metan, no torta, di’ak liu hili husi ai-hun molok sira fahe malu (iha Timor-Leste baibain Outubru to’o Abril). Pods bele loro-matan maran hodi ajuda sira loke ba estrasaun fini ne’ebé fasil. Tanba fini iha kazaku ne’ebé toos, hatauk antes kuda, idealmente ho mergulha iha bee ne’ebé besik atu tunu durante ~30 segundu no depois rega iha bee malirin durante oras 24, ne’ebé bele fó besik 75–90% jerminasaun. Kari 0.5–1 cm kle’an iha meiu ida ne’ebé drenajen di’ak (e.g., rai-henek ho kompos) iha polibag ka kama viveiru nian. Ho pre-tratamentu, jerminasaun hahú iha semana 1 nia laran no barak liu kompletu iha semana 2–3; lahó nia, jerminasaun neineik no la hanesan. Fornese sombra naroman durante semana 2–4, evita bee-matan, ai-oan mihis to’o ida kada saku, no transplanta iha fulan 3–4 bainhira ai-oan nia aas ~25–40 cm.', 'Acacia mangium dala barak hetan fuan moras no moras kór-roza, no ai-hun sira ne’ebé idade boot liu ka fraku mós bele hetan estragu maka’as husi insetu no termite ne’ebé halo ai-tahan ne’ebé halo ema baruk, ne’ebé bele halo fraku ai-tahan no hamenus kualidade ai. Fuan moras baibain subar iha tronku laran no dala barak hahú husi ai-sanak tuan nia korta ka kanek, nune’e prevene ho poda sedu ne’ebé moos. Moras kór-roza hatudu patch kór-roza iha ai-sanak ka ai-tahan, kauza sanak mate no dalaruma rahun, nune’e hamenus hodi la kuda besik liu, mihis tuir tempu ba fluxu ar ne’ebé di’ak liu, no mantein ai-horis saudavel ho kuidadu fatin ne’ebé di’ak no kontrolu du’ut. Ba problema rua ne’e, hasai no estraga ai-sanak ne’ebé infetadu, ferramenta ne’ebé moos, no hasai ai-horis ne’ebé hetan estragu aat sedu atu hapara espallamentu.', NULL),
(8, 'Alstonia scholaris', 'Ai‐hanek/Rite', 'Alstonia komemora botista Charles Alston, no matenek-na’in sira mak lian Latin ba “eskola sira,” refere ba ai-tahan nia uzu tradisionál ba halo hakerek ardózia/kabun-tahan.', 'Espésie ne’e akontese naturalmente iha Timor-Leste laran tomak, liu-liu iha área sira iha estrada ninin no mota sazonál sira.', 'Ai-hun ida ne’ebé aas tebes ho ai-tahan ne’ebé tetuk, bainhira tesi ka kanek nia hasai sap kole mutin; husik naruk no mos, agrupa iha anel 4–8 iha pontu ida iha ai-tahan; ai-funan iha agrupamentu sanak iha sanak nia rohan, mutin/kreme ki’ik no morin maka’as; ai-fuan naruk, mihis tebes, hanesan pods hanesan lapizeira ne’ebé baibain mai iha par, verde depois kór-kafé bainhira maran, fahe nakloke hodi hasai fini barak; fini ne’ebé kmaan tebes ho fuuk seda, fasil lori husi anin. Espésie ne’e bele identifika husi ai-funan hanesan anel 4–8 iha nodu no ai-fuan par naruk hanesan pod ho fini seda.', 'Simples', 'Folikulu', 'Flores: Maiu-Juñu; Frutador: Juñu-Jullu 2019.', 'Ai-fuan matenek-na’in alstónia nian mak folíkulu sira ne’ebé naruk no mihis ne’ebé tara iha forma V no maduru bainhira sira fila husi verde ba kór-kafé, sai maran no torta uitoan, no hahú fahe malu. Iha Timor-Leste, ai-fuan sira baibain maduru husi fulan Juñu to’o Setembru. Ba kolesaun ne’ebé moos, tesi ai-sanak ne’ebé fó fuan ka agrupamentu folikulu antes de’it sira loke no maran iha surat tahan ka saku malha, ka kesi saku malha hale’u folikulu iha ai-hun hodi kaer fini iha dehisénsia; evita ai-fuan ne’ebé maran hodi hamenus molde. Fini mak minutu, anin-dispersa ho fulun seda, no sira lakon viabilidade iha fulan balun nia laran, nune’e uza fini fresku no la presiza pré-tratamentu. Kuan fini iha superfísie kama ka bandeja ne’ebé di’ak, úmidu la ho hakoi, prense ho kmaan ka taka ho rai-henek ne’ebé mihis tebes husi rai-henek. Jerminasaun dala barak hahú iha loron 7–10 no barak liu kompletu iha semana 2 resin. Tau ai-oan iha ~50% nia okos, neon-nakali, kontrola du’ut, no transplanta ba polibag hafoin semana 4–6.', 'Matenek-na’in Alstónia dala barak sofre lalar ne’ebé han ai-funan bainhira ki’ik, no depois ai bele hetan estragu husi termite no borer ki’ik sira, ne’ebé halo fraku ai-hun no hamenus kualidade ai-tahan. Hamenus problema liu husi verifika ai-horis beibeik, hasai no estraga ai-funan/sanak ne’ebé afetadu ladi’ak, mantein área ne’e moos, no mantein ai-horis saudavel ho espasu di’ak no kuidadu báziku. Se ai-tahan tesi, maran no rai ho di’ak no hasai kualkér pedasuk infestadu sedu atu hapara espallamentu.', NULL),
(9, 'Calophyllum inophyllum', 'Too/Samplon', 'Calofillum mak husi kalos Gregu (“furak”) + phyllon (“daun”), no inofillu mak Gregu, refere ba ai-hun nia fulin ne’ebé nervozu/enuvadu besik.', 'Inofílolu Calofillum aumenta barak iha área tasi-ibun nian, liuliu iha Dili no Baucau nia sorin-sorin.', 'Inofillu calofillum hanesan ai-horis kosteira ida ne’ebé boot liu ho ai-horis ne’ebé boot liu, ho tronku ida ne’ebé metin loos no koroa ida ne’ebé densu, arredondadu; husik simples, tetuk no brillante, oval, ho vena paralelu barak ne’ebé di’ak; ai-funan ki’ik, mutin to’o kremosu no morin tebes, iha agrupamentu; ai-fuan ida ho kór verde redonda “hanesan nut” ne’ebé besik 2–4 cm liu ne’ebé sai mean-kafé bainhira tasak, ho fini toos iha laran; Espésie ne’e bele identifika husi ai-funan oval ne’ebé tetuk nabilan ho venas paralelu besik barak, ai-funan mutin ne’ebé morin, no ai-fuan verde-ba-kafé redonda.', 'Simples', 'Droga', 'Flores: Abril-Maiu; Frutador: Juñu-Agostu', 'Ai-fuan inofillu calofillum mak tapete redonda (3–5 cm) ne’ebé tasak husi verde no firme to’o mean-verde/kafé ho isin ne’ebé mos uitoan, ne’ebé taka fini ida iha fatuk ai-tahan ne’ebé toos. Iha Timor-Leste, halibur ai-fuan maduru sira husi fulan Juñu to’o Agostu, di’ak liu husi ai-hun ka foin monu iha loron hanesan; ai-fuan sira ne’ebé nakonu ho tasi-ibun ne’ebé nakonu iha bee-moos hodi hasai masin. Depulpa hodi rega durante kalan ida, hasai isin, fase, no hamrook-teen-maran ba tempu badak. Fini sei moris la ho pre-tratamentu, maibé kulit intaktu kauza jerminasaun neineik, escaldod durante fulan 2–4. Atu hetan rezultadu ne’ebé lalais liu, uniforme liu, hasai kulit no rahun ho jentil kulit ne’ebé ai-tahan hodi fratura, ne’ebé bele hamenus jerminasaun ba semana 3–8 resin. Kahuu 1–3 cm iha polibag nia klean (ida kada saku) ka kama espasu, uza mistura ida ne’ebé drenajen di’ak hanesan kompos:sand:batar kulit (1:1:1) iha ~50% nia okos sombra. Mantein úmidu hanesan, evita bee-matan, muda ai-oan ba loro-matan nakonu ho fulan ~2, no kuda sai iha fulan 5–6 (~25–30 cm aas) iha inísiu udan.', 'Inofillu calofillum baibain ai-hun tasi-ibun ida ne’ebé todan, maibé ai-horis joven no ai-horis ne’ebé fó fuan bele lakon nafatin área ai-funan no fó ai-fuan/mina menus se peste sira harii. Mineru daun sira halo liña mihis ka “tunnel” ne’ebé patchy iha ai-funan laran no bele kauza ai-horis nia ai-horis ki’ik tun lalais; kontrola sira liu husi verifikasaun regular, hasai no estraga ai-funan ne’ebé halo mina sedu, mantein ai-oan saudavel ho sombra balun, bee no kompos, no uza spray bazeia ba neem iha viveiru se presiza. Insetu eskala nian haree hanesan ai-sanak ki’ik sira iha ai-sanak no iha ai-funan okos no halo ai-funan sira sai kole ; hamenus sira hodi tesi no estraga ai-sanak sira ne’ebé infesta maka’as, fase/limpeza insetu sira husi ai-hun ki’ik sira ho bee simples (ka sabaun/bee-ain ne’ebé kmaan), no rega nem iha ai-funan nia okos no ai-sanak ne’ebé maluk.', NULL),
(10, 'Falcataria falcata', '', 'Falcataria refere ba “falcate” (forma sickle), deskreve forma folletu, no falcata mak lian Latin ba “forma sickle/rekurva hanesan sickle ida,” refere fali ba folhetu sira .', 'Falcataria falcata moris diak liu iha area rai-aas malirin liu iha Timor-Leste (hanesan Dare, Aileu, no Ermera) no baibain kultiva hanesan ai-hun sombra ba kafe.', 'Falcata falcataria hanesan ai-horis ida ne’ebé buras lalais tebes, dala barak aas 24–30 m (bele aas liu), ho ai-tahan ida ne’ebé loos no ai-tahan naruk ne’ebé moos; koroa iha área sira ne’ebé nakloke hanesan sumbriña ida; ai-funan kompostu, fulun, ho folhetu ki’ik barak ne’ebé kurva uitoan, no folhetu sira iha par barak; ai-funan mutin kremosu no ki’ik, hanesan sino ki’ik; ai-fuan ida ne’ebé latan ki’ik ida ho naruk besik 10–13 cm no luan ~2 cm, sai kór-kafé bainhira maran no fahe nakloke; fini 15–20 iha pod ida, ki’ik (~6 mm), nakukun mamuk; Espésie ne’e bele identifika husi ai-tahan ne’ebé aas loos ho koroa hanesan sumbriña, fulun ho ai-funan ho folhetu kurva ki’ik barak, no pods ne’ebé latan ki’ik.', 'Kompostu ho pina (Double)', 'Fó', 'Flores: Marsu to’o Juñu & Outubru to’o Dezembru; Frutador: Maiu to’o Agostu & Dezembru to’o Fevereiru 2019.', 'Falcataria falcata produz pods mihis, latan iha agrupamentu ne’ebé loos ne’ebé fila husi verde ba kór-kafé pálidu/nakukun uniforme, sai maran no papada; pods maduru hasai fini ki’ik barak ne’ebé latan. Kolekta pods antes deit sira naturalmente fahe malu, prefere liu husi ai-hun. Iha Timor-Leste, pods maduru tipikamente disponivel fulan Maiu–Agostu no dala ida tan fulan Dezembru–Fevereiru. Sun-maran pods badak to’o sira loke, depois hasai fini, sombra-maran, no rai iha kontentór ne’ebé taka metin ho ar. Fini iha dormansia ne’ebé hard-coat, nune’e pre-tratamentu liu husi fakar bee ne’ebé tunu liu fini no rega bainhira bee malirin durante oras 12–24. Kari 0.5–1 cm kle’an iha kama ka saku (2–3 kada saku, mihis depois) uza mistura rai-tetuk:sawdust (1:1). Ho tratamentu, jerminasaun lalais tebes (dala barak 80%+ iha semana ida nia laran, dalaruma iha loron 1–2); fornese sombra naroman iha de’it jerminasaun no muda ba loro-matan nakonu iha semana 1–2 nia laran, rega beibeik maibé evita bee-matan.', 'Falcataria falcata (sengan/falcata) moris lalais, maibé bele hetan infesaun husi ferrujen gal no borer-tahan, liuliu iha plantasaun ne’ebé densu, ai-hun ida de’it, ida ne’e bele hamenus kresimentu no bele mós oho ai-horis joven sira. Gall ferrujen kauza “folha” kór-kafé, áspera iha musan no sanak, dobra no buras buras, no dalaruma ai-sanak maran; hamenus nia hodi evita bloku puru ne’ebé nakonu ho ema (kahur ho ai-horis/ai-horis seluk), kuda de’it ai-oan ne’ebé saudavel moos, tesi no estraga ai-sanak ne’ebé iha biliar sedu, no hasai ai-horis ne’ebé infetadu ladi’ak. Atake borer iha ai-riin hatudu hanesan kuak ki’ik ho serra pó no ai-sanak ne’ebé mate iha kuak leten; jere ho espasu di’ak, verifikasaun regulár, oho grub iha kuak laran ho fiu no taka kuak ho rai-henek + karau-ten, no hasai ai-horis ne’ebé hetan ataka maka’as no estraga ai-tahan infestadu.', NULL),
(11, 'Canarium vulgare', 'Ai-Kiar', 'Kanariu mak husi malae/Molucan vernakular kanari/kenari, no vulgare mak lian Latin ba “komun/baibain,” posivelmente refere ba ninia akontesimentu gregáriu iha habitat .', 'vulgare kanáriu moris dala ruma tuir mota foho nian, liuliu iha Baguia no Liquica nia sorin-sorin.', 'Ai-hun ida ne’ebé aas to’o besik 45 m ho abut ne’ebé iha manteiga; ai-funan mak kompostu, baibain ho folhetu oval 9–11; ai-funan ki’ik no ketak hanesan mane no feto, ne’ebé lori iha agrupamentu iha sanak nia rohan; ai-fuan ne’e isin, oval no mos, verde bainhira sei ki’ik no nakfilak kór-roxu nakukun ba metan bainhira tasak; iha ai-fuan laran iha fatuk toos ida ho kernel laran ne’ebé bele han; Espésie ne’e bele identifika husi ai-funan 9–11 nia fuan no ai-fuan oval ne’ebé lisa ne’ebé sai kór-roxu nakukun/metan ho kernel ne’ebé bele han iha laran.', 'Kompostu ho maneira ne’ebé ho maneira ne’ebé ho maneira ne’ebé kompoin (ida de’it)', 'Droga', 'Flores: Setembru to’o Dezembru; Ai-fuan: Maiu to’o Jullu 2019.', 'vulgare Canarium produz drpus ovoid ne’ebé mos, ovoid ne’ebé tasak husi verde to’o kór-roxu nakukun, ho isin ne’ebé maluk no fatuk ida ne’ebé toos tebes ne’ebé taka kernel oleozu. Kolekta ai-fuan sira ne’ebé maduru husi fulan-Maiu to’o fulan-Jullu bainhira nakukun no toos tomak, di’ak liu hili husi ai-hun ka halibur beibeik husi rai, soe ai-fuan sira ne’ebé hetan estragu husi insetu ka molde. Depulpa no loro-matan maran fatuk sira; fatuk maran bele rai durante fulan barak (dala barak to’o ~1.5 tinan) ho lakon viabilidade uitoan. Tanba endokarpu maka''as atraza jerminasaun, pre-tratamentu ho fatuk sira ne''ebé rega durante loron 2, depois ho laran-maus rahun ka nick/arkivu rohan ida hodi husik bee tama. Kain 3–5 cm kle''an iha meiu ida ne''ebé drenajen di''ak (rai:kompostu 1:1:1), idealmente horizontalmente ka ho sorin ne''ebé rahun ba kraik uitoan, iha ~50% nia okos. Mantein konsistentemente úmidu maibé drenadu ho di’ak. Ho ransu, jerminasaun bele hahú iha semana 6–8 no kontinua liu fulan 2–3, enkuantu fatuk ne’ebé la hetan tratamentu bele lori fulan 6–12. Mantein sombra no fluxu ar, depois neineik-neineik toos to’o naroman aas liu; transplantasaun iha fulan 6–9 (aas besik 20–30 cm) iha inísiu udan.', E'vulgare kanáriu baibain hardy, maibé ai-horis joven, musan no ai-fuan bele nafatin hetan estragu no fó kresimentu neineik liu ka produsaun ne’ebé ki’ik liu. Termita sira bele halo baze, no hamosu derrepente derrepente; hamenus ida ne’e hodi uza ai-oan ne’ebé forte, hamoos ai-tahan tuan/lixu ai-laran, hadook mulsa husi ai-tahan, no uza kompos ne’ebé iha rot ho di’ak.\nBug ai-han ne’ebé fó han bele halo metan ponta tiru no estraga ai-funan/ai-fuan; jere ho espasu di’ak, poda no estraga musan ne’ebé hetan estragu, verifikasaun regulár, hili liman sedu, no rai ai-horis ne’ebé iha ai-funan besik ba insetu sira ne’ebé ajuda.', NULL),
(12, 'Casuarina equisetifolia', 'Han-kakeu', 'Casuarina mai husi liafuan malae kasuari (cassowany), refere ba ai-hun nia ai-sanak hanesan ai-sanak ne’ebé hanesan manu-fuik nia fulun, no ekisetifolia mak latin ba “husik husi kuda-matan,” ne’ebé deskreve ninia ai-funan mihis no artikulasaun hanesan ho Ekisetum (ai-horis kuda-matan).', 'Ekisetifolia Casuarina aumenta barak iha Timor-Leste laran tomak, akontese naturalmente iha area tasi ibun, no nia mos moris diak iha tipu rai oioin.', 'Ai-hun ida ne’ebé boot tebes dala barak aas 10–30 m;  Husik hela hanesan fiu hanesan agulha verde mihis; ai-gris-kafé no áspera; ai-funan ki’ik tebes no la hatudu, ai-funan mane iha spike mihis no ai-funan feto hanesan ai-horis ki’ik; ai-fuan haree hanesan ai-tahan ki’ik ida , verde depois kór-kafé, loke bainhira maran; fini ki’ik tebes no latan ho ala ne’ebé mihis, lori ho anin; Espésie ne’e bele identifika husi ai-sanak ne’ebé hanesan agulha sanak artikulasaun verde no ai-fuan ki’ik hanesan kóniku.', 'Simples', 'Kapsula', 'Flores: Setembru to’o Outubru; Ai-fuan: Fevereiru to’o Juñu.', 'Ekisetifolia Casuarina produz ai-fuan ki’ik, hanesan kóniku ai-tahan ne’ebé maduru husi verde to’o ai-tahan ka kastanha-kafé no sai maran no frajil bainhira sira tasak. Konus maduru loke naturalmente hodi hasai fini ki’ik, ho ala no rekolla di’ak liu bainhira sira destaka ho fasil ka monu hafoin anin, baibain entre Fevereiru–Marsu no dalaruma fali iha fulan Juñu–Jullu. Konus ne’ebé kolekta tenke maran iha loro-matan durante loron balun to’o eskala sira loke no fini sira sai. La presiza pre-tratamentu. Katar fini ho kle’an (besik 0.5–1 cm) iha meiu ida ne’ebé drenajen di’ak hanesan rai-henek ka mistura rai-henek–rai, taka ho kmaan no mulsa atu prevene fase-liman. Germinasaun hahú iha loron 5–10 nia laran no barak liu kompletu iha semana 2–3. Tau kama úmidu maibé la’ós bee-matan, no mantein loro-matan nakonu. Prick out ai-oan iha semana 3–4 ba iha polibag, no transplanta ba to’os ho fulan 3–4 resin bainhira aas 15–20 cm.', E'Peste boot mak lalar ne’ebé fó han kulit ne’ebé halo kuak no túnel iha ai-tahan no sanak, ne’ebé bele halo fraku ai-hun. Métodu simples ida ne’ebé la’ós kímiku mak kontrolu mekániku, buka túnel ne’ebé loke no taka ho material hanesan alkatraun/lian atu nune’e larva labele kontinua. Infestasaun dala barak sa’e hafoin udan kontinua no baibain menus iha kondisaun ne’ebé manas liu, maran liu, nune’e kuda iha fatin ne’ebé adekuadu no alerta estra hafoin períodu udan ajuda hamenus estragu.\nCasuarina mós bele hetan mealybugs (insetu ki’ik, mutin, hanesan koto) ne’ebé tuur iha ai-tahan no ai-tahan joven no ai-horis nia ai-horis. Dala barak sira husik kamada ida ne’ebé kole, ne’ebé depois bele nakfilak ba fungo sooty metan, no ai-hun ne’e bele haree fraku, mean no buras neineik. Kontrola nia hodi fase/limpeza sira iha ai-hun ki’ik sira, tesi no estraga ai-sanak sira ne’ebé infesta maka’as, no rega mina neem/mestura bazeia ba neem iha parte sira ne’ebé afetadu ; mós halo área ne’e moos no hamenus formigas, tanba formigas proteje peste sira ne’e.', NULL),
(13, 'Pterocarpus indicus', '', 'Pterocarpus mai husi pteron Gregu (“ala”) + karpos (“ai-fuan”), refere ba ninia pods fini ala, no índico mak lian Latin ba “indianu/indianu,” ne’ebé aponta ba ninia asosiasaun ho rejiaun India ho naran botánika sedu.', 'Pterocarpus índico buras iha estrada ninin foho-lolon no baibain iha Timor-Leste tomak.', 'Ai-horis ida ne’ebé sempre verde to’o semi-deciduous to’o besik 40 m, koroa ida ho forma kúpula ne’ebé espalla no sanak sira ne’ebé monu, kulit rahun uitoan no eskala; bainhira tesi bele ooze sap mean; ai-funan alterna no kompostu, ai-funan iha agrupamentu sanak husi artikulasaun daun no sanak nia rohan, mean nabilan, morin, besik 1,5 cm; ai-fuan ida ne’ebé redonda hanesan disko ne’ebé latan ho ala luan iha ninin, verde no fulun uitoan bainhira ki’ik, sai kór-kafé pálidu no mos bainhira tasak, no nia la fahe nakloke; fini 1–2 kada pod, kór-kafé; Espésie ne’e bele identifika husi ai-funan ne’ebé morin mean no vagem ki’ik hanesan disko ho ala redonda.', 'Kompostu ho maneira ne’ebé ho maneira ne’ebé ho maneira ne’ebé kompoin (ida de’it)', 'Fó', 'Flores: Agostu to’o Setembru; Ai-fuan-Maiu to''o Juñu', 'Pterocarpus índico produz redonda distintiva, pods ho ala ( luan 4–6 cm) ne’ebé fila husi verde ba ai-sunu-kafé bainhira sira maduru, sai maran no papela ho fini sentrál ne’ebé toos. Iha Timor-Leste, pods baibain rekolla durante tempu maran (besik Juñu–Jullu) bainhira sira kór-kafé no metin tomak, di’ak liu antes sira monu. Pods sira ne’e indezisente, nune’e fini sira taka metin hela; trimming ka parsialmente tesi ala ajuda hadi’a kontaktu rai no absorsaun umidade. Harii pods tomak iha rai leten, hanehan sira ho kmaan ba iha meiu rai-henek ka rai-henek ne’ebé drenajen di’ak no taka ho kmaan tebes. Mantein kama ne’e úmidu maibé la’ós bee-matan. Jerminasaun tipikamente hahú iha loron 3–4 nia laran iha kondisaun manas. Fornese sombra naroman no fluxu ar di’ak, no du’ut beibeik. Bainhira ai-oan sira dezenvolve ai-funan loloos oioin, transplanta ba polibag no neineik-neineik sai toos antes kuda to’os ho aas 15–20 cm.', 'Pterocarpus indicus bele afetadu maka’as husi moras ne’ebé sulin, iha ne’ebé ai-funan sai mean, ai-sanak maran kotuk, no ai-hun tomak bele mate, no nia mós bele hetan mineiru daun no ai-kabelak ne’ebé halo ai-funan sai deformadu ka halo fraku ai-tahan. Estratéjia ida ne’ebé di’ak mak kuda de’it ai-oan ne’ebé saudavel, mantein espasu di’ak no kuda kahur, no evita hakanek ai-kulit durante hamoos du’ut ka poda.', NULL),
(14, 'Delonix regia', 'Ai‐kesi/Madre‐Kakau/Samatuku Marae', 'Delonix mai husi delos Gregu (“klaru/vizivel”) + onyx (“claw”), refere ba ninia pétala ne’ebé hatudu, hanesan kukun, no regia mak lian Latin ba “aldeia”, deskreve ninia ai-funan boot no flamboyant.', 'Regia Delonix baibain kuda iha estrada ninin no ema barak haree iha nasaun tomak.', 'Ai-horis ida ne’ebé deciduous ba semi-evergreen ho medida média, ho sumbrinha ida ne’ebé luan tebes hanesan sumbriña ne’ebé espalla koroa no sombra ne’ebé todan, tronku dala barak badak ho sanak sira ne’ebé espalla ki’ik, kulit-mutin-kafé no justu mos to’o rahun uitoan; Husik hela ai-funan kompostu duplu boot, fulun, hanesan samake ne’ebé halo husi folhetu ki’ik barak; Ai-funan boot, showy tebes, mean nabilan to’o laranja-mean, dala barak ho pétala ida ne’ebé marka ho mean/mutin; Ai-horis nia naruk, latan, ai-tahan toos ne’ebé tara tun, sai kór-kafé nakukun bainhira tasak, baibain naruk 30–60 cm; Fini maka’as, fini kór-kafé oval ne’ebé arranja iha liña ida iha pod laran; Espésie ne’e bele identifika husi ninia ai-funan hanesan ai-sasan, ai-funan mean-laranja nabilan, no pod ai-tahan ne’ebé tara naruk.', 'Kompostu ho pina (Double)', 'Fó', 'Flores: Abril to’o Maiu; Frutador: Outubru to’o Dezembru 2019.', 'Delonix regia produz pods naruk, ai-tahan (30–60 cm) ne’ebé sai metan metan no toos bainhira maduru, baibain husi fulan Maiu to’o fulan Jullu. Tenke rekolla pod ne’ebé maduru diretamente husi ai-hun ne’ebé bainhira maran hotu ona, depois loro-matan maran liután no fahe nakloke liután hodi hasai fini ne’ebé lahan no toos. Fini sira iha kazaku ida ne’ebé todan tebes, nune’e eskarifikasaun esensiál—ka hodi hatama fini nia kazaku ka rega iha bee manas to’o book an. Katar fini ne’ebé halo tauk 0.5–1 cm kle’an iha rai-henek ka rai-henek-loam, espasu ho kmaan se iha kama. Germinasaun lalais bainhira hetan tratamentu, ho abut ne’ebé mosu iha loron 4–7 no maioria fini ne’ebé moris iha semana rua nia laran. Fornese sombra naroman iha inisiu no mantein rai úmidu maibé drenadu ho di’ak. Ai-oan moris lalais no bele transplanta iha semana 3–4 bainhira besik 10–15 cm aas, neineik-neineik sai toos ba loro-matan nakonu.', 'Espésie ne’e dala barak hetan infesaun ho abut ne’ebé moras, liu-liu iha fatin ne’ebé udan boot, ne’ebé estraga neineik-neineik abut no hafraku ai-hun tomak. Nia mos hetan ataka husi besouro ki’ik no sira nia oan, ne’ebe fura ba iha fini nia vagem no halo kuak atu nune’e fini sira suli sai. Dalaruma insetu sira ne’ebé halo shot-boring estraga kresimentu foun ne’ebé ternu, hamenus ramu saudavel. Iha kazu balun, lalar/insetu sira ne’ebé han ai-funan bele hasai ai-funan barak liu ka mezmu hotu.', NULL),
(15, 'Tamarindus indica', 'Ai‐sukaer', 'Tamarindus mai husi fraze árabe tamr e kotuk signifika “Data India,” refere ba ninia pulpa hanesan data, no índiku mak lian Latin ba “indiana/indianu,” ne’ebé aponta ba ninia asosiasaun naruk ho Índia ho naran sedu.', 'Tamarindus indica ne’e baibain no barak, liu-liu iha aldeia sira nia sorin-sorin.', 'Ai-horis ida ne’ebé moris naruk ba médiu to’o semi-deciduous, ho ai-tahan ida ne’ebé tetuk no koroa luan, arredondadu, ne’ebé espalla ne’ebé fó sombra kle’an; Husik ai-funan ki’ik, ho oin-midar ne’ebé haree ho oin-midar ho folletu ki’ik barak, fó oin fulun ne’ebé di’ak; Ai-funan ki’ik, iha agrupamentu badak, mean pálidu to’o kreme ho streak mean/laranja ne’ebé di’ak, la’ós showy tebes; Ai-fuan ne’ebé tetuk, kurva ba pods kór-kafé loos, maran no frajil uitoan bainhira tasak, ho pulpa midar-moruk ne’ebé kole iha laran; Fini toos, mos, brillante metan metan ne’ebé nakonu iha pulpa laran; Espésie ne’e bele identifika husi koroa sombra ne’ebé densu, ai-funan fulun ne’ebé di’ak, no pods kór-kafé ho pulpa ne’ebé bele han midar ne’ebé kole.', 'Kompostu ho maneira ne’ebé ho maneira ne’ebé ho maneira ne’ebé kompoin (ida de’it)', 'Fó', 'Flores: Juñu to’o Jullu; Frutador:Marsu 2019.', 'Tamarindus indica produz pods ne’ebé alongadu, frajil ne’ebé sai kór-kafé no maran bainhira maduru, taka fini balun ne’ebé toos, brillante iha pulpa ne’ebé kole. Iha Timor-Leste, ai-fuan sira baibain maduru husi fulan Juñu to’o Setembru no di’ak liu rekolla diretamente husi ai-hun ne’e bainhira kór-kafé tomak atu evita estragu insetu ka umidade. Depois de rekolla, hasai pulpa, hamoos fini, no sombra-maran antes armazenamentu. Fini Tamarind iha kazaku ne’ebé toos no presiza pre-tratamentu ba jerminasaun di’ak; soaking iha bee manas (besik 80 °C) no sai atu malirin durante oras 12–24, ka halo nicking uitoan ba kazaku fini, hadi’a tebes rezultadu. Kuan fini besik 1 cm kle’an iha rai-henek ka rai-henek ne’ebé drenajen di’ak, tantu iha polibag ka kama viveiru nian. Jerminasaun baibain hahú iha loron 5–10 nia laran no barak liu kompletu iha semana 2–3. Fó mahon naroman iha inisiu, depois neineik-neineik espoin ai-oan ba loro-matan nakonu. Ai-oan moris lalais no prontu ba transplantasaun ho idade besik fulan 3.', 'Ai-horis tamarind bele afetadu aat ho insetu ki’ik ne’ebé susu (hanesan eskala no refeisaun) no insetu ne’ebé lori ba vazu, fini, ka sanak, ne’ebé bele hamenus kuantidade ai-fuan di’ak ne’ebé ita bele fa’an. Fatin ne’ebé la hanesan relata problema ne’ebé la hanesan—área balun haree besouro, termite, ka peste ne’ebé hahan ba pod ne’ebé ataka tamarind ne’ebé rai tuir kolleita. Iha époka balun, ai-fuan borer bele sai hanesan kestaun boot ida no rendimentu ne’ebé bele fa’an maka’as. Tamarind mós bele hasoru moras ai-horis oioin ne’ebé mosu hanesan marka daun ka pó mutin iha ai-funan, revestimentu molde metan, no ai-tahan ne’ebé dodok ka estraga, abut, ai, ka kulit.', NULL),
(16, 'Eucalyptus urophylla', '', 'Eucalyptus mai husi eu Gregu (“di’ak”) + kalipto (“kobre”), refere ba ai-funan-fuan ne’ebé taka metin, no urofilla mai husi lian Gregu usa (“ikun”) + phyllon (“daun”), signifika “husik ikun,” deskreve ninia forma ai-funan ne’ebé menus.', 'Eucalyptus urofilla dala ruma hetan iha estrada foho-lolon ho altitude aas no área foho nian, liuliu iha Dare, Aileu, Ermera, no Baguia nia sorin-sorin.', 'Ai-hun ida ne’ebé aas liu verde ne’ebé bele moris besik 45–55 m, baibain ho ai-tahan ne’ebé loos; kulit baibain persistente, justu lisa no fibrosa uitoan, mean-kafé to’o kór-kafé ho ransu ho naruk ne’ebé kle’an, dalaruma áspera liu besik baze; Ai-funan joven barak liu iha par opostu, luan no ho forma lansu; ema adultu husik naruk, ho forma ki’ik-lance, kaer alternadu to’o besik-oin; Ai-funan ki’ik, iha agrupamentu ki’ik husi artikulasaun daun nian; Ai-fuan ki’ik, kapsula ai-tahan maran, ho forma kopu ba hanesan kóniku; Fini ki’ik tebes, metan, no ho forma kurvadu/fulan-meia uitoan; urofila eucaliptus bele identifika husi E. alba husi ninia ábitu jeralmente aas liu, loos liu, ninia akontesimentu baibain iha leten besik 500 m altitude, no ninia kulit mean-kafé (dala barak ho fissura ho naruk ne’ebé kle’an) envezde kulit pó mutin/krem husi E. alba.', 'Simples', 'Kapsula', 'Flores: Dezembru to’o Janeiru; Ai-fuan: Abril to’o Maiu;', 'Urfíl eucalyptus produz fini ki’ik, ne’ebé mai husi kapsula ne’ebé hasai bainhira kapsula ne’ebé maduru maran no nakloke. Fini sira rekolla husi kapsula ne’ebé dezenvolve hotu ona, maran, no hamoos antes armazenamentu ka kuda. Ba jerminasaun ne’ebé di’ak liu, fini hetan benefísiu husi estratifikasaun malirin liu husi halo sira úmidu no refrijeradu durante semana 4–6, ne’ebé ajuda atu sobu dormansia fiziolójika. Hafoin tratamentu, fini sira iha superfísie ne’ebé kuda iha meiu ne’ebé di’ak, drenajen di’ak hanesan rai no rai-henek, no prense uitoan lahó taka. Jerminasaun akontese di’ak liu iha 20–25 °C iha naroman ne’ebé suave no ventilasaun di’ak, baibain iha semana 2–3 nia laran. Ai-oan sira transplanta ba polibag hafoin loron 30 bainhira sira dezenvolve 2–4 ai-funan loloos. Ai-horis joven sira prefere loro-matan nakonu no rai ne’ebé drenajen di’ak, ásidu uitoan. Ho kuidadu ne’ebé di’ak, Eucalyptus buras lalais, dala barak to’o metru balun iha altura iha tinan dahuluk nia laran .', 'Amblypelta no Amorbus hanesan peste hanesan bug ne’ebé prejudika eukaliptu hodi perfura ai-horis joven sira no hemu ai-horis nia sanak. Iha ai-hun sira ne’ebé joven tebes, ida ne’e bele halo ponta musan sira mout no mate fali, dalaruma oho ai-horis prinsipál leten no husik ai-hun ne’e haree hanesan buras ka hanesan hedge. Opsaun kontrolu naturál la estuda ho di’ak, maibé mina neem no kuda ai-horis seluk iha sorin (intercropping) dalaruma sujere.', NULL),
(17, 'Eucalyptus alba', 'Ai‐porize', 'Eucalyptus mai husi eu Gregu (“di’ak”) + kalipto (“kobre”), refere ba bud nia kapa, no alba mak lian Latin ba “mutin,” refere ba ai-hun nia kulit ne’ebé pálidu/mutin.', 'Alba Eucalyptus moris barak iha foho-lolon sira iha tasi-ibun ho altitude ki’ik, liuliu iha korredór Dili–Baucau nia sorin.', 'Ai-hun ki’ik to’o médiu baibain aas besik 5–18 m, ho koroa ne’ebé espalla ho luan besik 5–15 m, tronku dala barak dobrada; ai-tahan ne’ebé moos, pó, no kór-roza-mean to’o kór-kma’an ka kór kreme, dala barak haree pálidu husi dook; Husik ai-horis joven sira alterna, luan no ho forma ovo to’o kuaze redonda, justu boot; ema adultu nia ai-funan ho forma ovo ba ai-funan ho forma lansa, ki’ik liu fali ai-funan juvenil; Ai-funan nia musan iha agrupamentu hitu iha ai-tahan badak, ai-funan mutin; Ai-fuan ki’ik, ai-tahan, ho forma kóniku to’o metade-round; Fini ki’ik no típiku husi eukaliptu; Espésie ne’e bele identifika husi nia aas badak liu, tronku ne’ebé dobrada, no kulit mutin/cream pó ho agrupamentu ai-funan mutin.', 'Simples', 'Kapsula', 'Flores: Dezembru to’o Janeiru; Ai-fuan: Abril to’o Maiu;', 'Eucalyptus alba produz fini ki’ik tebes, hanesan rai-rahun ne’ebé taka iha kapsula ai-tahan ki’ik ne’ebé dezenvolve iha agrupamentu sira iha sanak sira nia sorin. Nu’udar kapsula sira sai maduru, sira muda husi verde ba kór-kafé kmaan no sai maran no metin. Kolesaun fini tenke halo diretamente husi ai-hun antes deit kapsula sira fahe nakloke naturalmente, tanba bainhira sira loke fini fina ne’e fasil lakon. Kapsula ne’ebé halibur bele loro-matan maran iha bandeja ka kaixa durante loron balun to’o sira hasai fini, ne’ebé depois bele hamoos no rai maran. Ba jerminasaun, la presiza pre-tratamentu. Fini tenke transmite ho kmaan iha superfísie husi meiu ida ne’ebé di’ak, drenajen di’ak hanesan rai-henek ka mistura rai-henek–rai no prenxe ho laran-maus la taka. Mantein umidade naroman no fluxu ar ne’ebé di’ak. Jerminasaun baibain hahú iha loron 7–14 nia laran iha kondisaun manas.', 'Amblypelta no Amorbus hanesan peste hanesan bug ne’ebé prejudika eukaliptu hodi perfura ai-horis joven sira no hemu ai-horis nia sanak. Iha ai-hun sira ne’ebé joven tebes, ida ne’e bele halo ponta musan sira mout no mate fali, dalaruma oho ai-horis prinsipál leten no husik ai-hun ne’e haree hanesan buras ka hanesan hedge. Opsaun kontrolu naturál la estuda ho di’ak, maibé mina neem no kuda ai-horis seluk iha sorin (intercropping) dalaruma sujere.', NULL),
(18, 'Parkia speciosa', 'Vomo/Moras/Moas .', 'Paránia komemora esploradór eskoses Mungo Park, no espesiosa mak lian Latin tanba “showy” ka “furak”, refere ba ai-funan ne’ebé marka.', 'Partia spesiosa la’ós buat baibain no liuliu hetan hanesan ai-hun uma-kain ne’ebé kuda iha aldeia sira ho altitude aas liu, liuliu iha Dare, Aileu, no Ermera nia sorin-sorin.', 'Ai-hun ida ne’ebé aas médiu–boot besik 15–40 m, ho ai-sanak ki’ik dala barak fulun uitoan; Husik hela ai-funan boot, fulun, kompostu duplu ho folheta ki’ik par barak; Ai-funan kreme-mutin, ka mean-mutin, embala metin iha ulun densu ne’ebé hatudu; Ai-fuan boot ho naruk besik 35–55 cm, loos ka baibain liu torta, tara iha faskulante ki’ik, verde bainhira sei ki’ik no sai metan bainhira tasak, kada vagem ne’ebé kaer fini boot besik 10–18; Fini boot,no fini sira ne’e bele han no baibain han hanesan ai-horis (nota ba gostu hanesan ai-horis no morin maka’as tebes); Espésie ne’e bele identifika husi fulun fulun no pods naruk ne’ebé tortu ne’ebé tara iha grupu ho fini ne’ebé bele han boot iha laran.', 'Kompostu ho pina (Double)', 'Fó', 'Flores: Maiu to’o Juñu; Ai-fuan: Agostu to’o Setembru 2019.', 'Paránia spesiosa (petai/farina foer) mai husi vazu naruk ne’ebé iha fini boot balun. Atu hetan rezultadu di’ak liu, halibur pod maduru diretamente husi ai-hun bainhira sira dezenvolve tomak atu evita estragu insetu no problema fungal, depois loke pods hodi hasai fini lakleur depois kolleita. Fini iha kazaku fini ne’ebé toos ne’ebé bele atraza jerminasaun, nune’e kultivadór barak mak hasai fini nia kazaku ka nick fini besik mikropilu hodi ajuda bee tama no aselera moris. Hamoos fini iha bee laran molok kuda mós ajuda hadi’a uniformidade jerminasaun. Fini sira kuda iha superfísie mistura ida ne’ebé drenajen di’ak hanesan rai-henek ka mistura rai-henek–rai no prenxe ho kmaan lahó taka kle’an, tanba kontaktu kmaan ho umidade enkoraja moris. Iha kondisaun di’ak, fini ne’ebé trata tipikamente hahú moris iha loron 10–15 resin nia laran, no jerminasaun uniforme no kresimentu ai-horis ne’ebé vigorozu tuir ho umidade no naroman ne’ebé adekuadu .', 'Espesiosa Parnia bele hetan estragu husi insetu no fungi ne’ebé halo ai ne’ebé mancha ka estraga ai-tahan, no ai-tahan liur ne’ebé suave liu fasil liu ba baruk sira atu ataka. Iha area balun, larva moth mos bele estraga fini. Ai-fuan, ai-funan, ai-funan, no ai-kulit bele han husi animál no manu hanesan ai-tahan, samea, no eskudu. Jestaun inklui mantein ai maran no proteje ho diak hafoin tesi, hasai parte sira ne’ebé hetan ataka maka’as sedu, no uza protesaun fíziku simples hanesan esgrima ka guarda sira ne’ebé estragu ba animál fuik sira hanesan buat baibain.', NULL),
(19, 'Terminalia catappa', '', 'Terminalia refere ba ai-funan sira ne’ebé agrupa iha “finál” sanak sira-nian (husi terminalis latinu), no katappa mai husi naran lokál/komún katappa ne’ebé uza iha parte balun iha Ázia Súl no Sudeste ba ai-hun ida-ne’e.', 'Katappa Terminalia baibain moris iha area kosteira.', 'Ai-hun boot ida ne’ebé deciduous ba semi-evergreen, ho korvo ida ne’ebé distintu tebes, hanesan pagoda; Husik boot tebes, luan, no kulit, ne’ebé halibur besik sanak nia rohan, sai mean ba kór laranja-mean molok monu; Ai-funan ki’ik, verde-mutin, iha agrupamentu hanesan spike ne’ebé mihis husi artikulasaun daun nian, la’ós showy; Oval ai-fuan to’o ho forma amêndoa, latan uitoan no mos, verde bainhira joven, sai mean, mean ka kór-roxu bainhira nia tasak, ho kamada liur fibrosa; Fini “fatuk” ida ne’ebé toos iha ai-fuan laran ne’ebé iha kernel ne’ebé bele han (dala barak hanaran amêndoa tropikál); Espésie ne’e bele identifika husi ramu “pagoda” ho nivel latan, ai-funan boot tebes ne’ebé mean antes soe, no ai-fuan sira hanesan amêndoa ho kernel ne’ebé bele han.', 'Simples', 'Droga', 'Flores: Maiu to’o Juñu; Frutador: Abril to’o Juñu 2019.', 'Katappa terminalia produz drope ovoid ne’ebé sai husi verde ba mean ka mean-kafé bainhira maduru, taka fatuk ida ne’ebé toos, ai ho fini iha laran. Ai-fuan sira ne’ebé maduru mak di’ak liu rekolla entre Abril no Juñu, di’ak liu hili diretamente husi ai-hun ka halibur fresku husi rai. Depois de rekolla, tenke hasai kamada liur isin nian no porka sira fase no matabisu. Tanba atraza endokarpu ne’ebé toos ne’e halo jerminasaun, rahun ho kmaan kulit ka rega ai-fuan ne’e iha kalan ida nia laran hadi’a tebes rezultadu. Fini sira kuda besik 2 cm kle’an iha rai-henek ne’ebé drenajen di’ak ka meiu rai-henek ne’ebé drenajen ho di’ak, prefere liu tau rai-lolon. Mantein úmidu médiu maibé la’ós bee-moos. Jerminasaun baibain hahú iha semana 3–8 nia laran, lalais liu bainhira kulit rahun. Rekomenda ai-horis ai-oan ida ne’ebé forte, nune’e rekomenda transplantasaun sedu ba iha kontentór kle’an. Sombra kmaan no rega regular suporta kresimentu sedu ne’ebé saudavel.', 'Katappa terminalia baibain hetan problema peste bainhira nia sei joven, liuliu husi insetu sira ne’ebé han ai-funan ne’ebé bele hasai ai-funan barak. Kestaun komún seluk mak insetu ki’ik sira ne’ebé hanaran thrips ne’ebé estraga ai-funan, halo sira haree bronze ka sunu, no bele kauza ai-funan nia drop sedu. Estratéjia di’ak liu mak verifikasaun regulár, hasai peste ho liman iha ai-hun ki’ik sira, no tesi no estraga ho seguru ne’ebé afetadu ladi’ak ai-funan no tiru.', NULL),
(20, 'Peltophorum pterocarpum', 'Ita iha silo/Ita iha inan .', 'Peltophorum mai husi peltē Gregu (“eskursu ki’ik”) + phoros (“orienta”), refere ba ninia pods hanesan eskudu, no pterocarpum mai husi pteron Gregu (“ala”) + karpos (“ai-fuan”), signifika “fruit-ala.”', 'Pterocarpum pelforum moris iha estrada ninin foho-lolon.', 'Ai-horis ida ne’ebé buras lalais ba médiu-asidu to’o semi-deciduous , ho koroa luan ida ne’ebé arredondadu no ai-sanak ne’ebé espalla, ai-tahan kulit-mutin no áspera ho ransu bainhira nia sai boot; Husik hela ai-funan kompostu boot, fulun, duplu ho folhetu ki’ik barak ne’ebé fó oin hanesan samake ne’ebé maluk; Ai-funan sira ne’ebé nabilan ho mean-mean, morin uitoan, ne’ebé lori iha agrupamentu boot ne’ebé hamriik loos iha sanak sira-nia rohan, dala barak halo koroa tomak haree mean bainhira iha ai-funan; Ai-fuan ne’ebé lahan, mihis, ai-tahan, oval to’o oblonga, mean-kafé to’o kór-kafé nakukun bainhira tasak, baibain la fahe nakloke; Fini 1–4 fini kada pod, toos no kór-kafé; Espésie ne’e bele identifika husi agrupamentu ai-funan mean-mean-mean boot no pods ai-tahan ho kór mean-kafé ne’ebé latan hamutuk ho ai-funan kompostu duplu fulun.', 'Kompostu ho pina (Double)', 'Fó', 'Flores: Abril to’o Maiu; Frutador: Abril to’o Juñu 2019.', 'Pterocarpum pelforum produz pods ne’ebé lahan, ai-tahan ne’ebé nakfilak husi mean coppy ba kór-kafé nakukun ka metan bainhira maduru. Kada pod iha fini 1–4 ne’ebé toos, ne’ebé latan. Pod ne’ebé maduru rekolla husi ai-hun entre fulan Abril no Juñu, maran to’o sira fahe malu ho fasil, no fini sira hamoos. Tanba fini sira iha kazaku ne’ebé toos tebes, pre-tratamentu esensiál: rega iha bee laran-temperatura durante oras 24 ka badak iha bee manas hadi’a tebes jerminasaun. Kuan fini besik 1 cm kle’an iha rai-henek ida ne’ebé drenajen di’ak no rai-henek, taka ho kmaan. Jerminasaun baibain hahú iha semana 1–2 nia laran bainhira hetan tratamentu ho di’ak. Fó mahon naroman durante moris sedu, depois neineik-neineik espoin ai-oan ba loro-matan nakonu. Mantein rega regularmente la ho bee-matan. Ai-oan moris lalais no bele transplanta hafoin semana 4–6 bainhira aas besik 10 cm.', 'Pterocarpum pelforum baibain hardy, no maioria problema mak insetu han ai-funan dala ruma de’it. Bagworms bele haree husi “saku” ki’ik sira ne’ebé tara husi ai-funan no ai-sanak, no sira neineik-neineik halo kanopi ne’e mihis hodi han ai-funan. Lalar ba looper bele hasai folha no halo koroa ne’e haree mihis ka besik la iha ai-funan durante surtu, liu-liu iha ai-horis ki’ik sira. Estratéjia simples mak atu mantein ai-horis sira forte, haree beibeik, enkoraja manu no insetu sira ne’ebé ajuda, no liman-pick ka poda no estraga parte sira ne’ebé infestadu maka’as bainhira problema ne’e ki’ik.', NULL),
(21, 'Santalum album', 'Ah‐kamelu', 'Santalum mai husi sandália liafuan árabe–pérsia nian (sandalwood), no álbun mak lian Latin ba “mutin,” refere ba ninia ai pálidu (liuliu ai-sapwood).', 'Iha Timor-Leste, álbun Santalum moris naturalmente iha ai-laran monsaun maran/scrub, di’ak liu iha rai-henek ka rai-henek ne’ebé drenajen di’ak .', 'Ai-hun ki’ik to’o médiu ne’ebé sempre verde, baibain ho ai-tahan ne’ebé mihis no koroa redonda, ai-kulit kinur to’o kór-kafé nakukun no áspera ho idade; ai-kabelak ne’e fragrante tebes ; Husik simples, kontráriu, lisa no kulit, verde médiu no nabilan uitoan; Ai-funan ki’ik, iha agrupamentu badak husi artikulasaun daun, verde to’o kremosu bainhira joven no dala barak sai mean-kafé ka kór-roza bainhira sira sai boot, fragrante kmaan; Fruta redonda ki’ik ida to’o oval drpu isin nian, verde bainhira joven no sai metan-mutin bainhira tasak; Fini sira baibain fini toos ida iha ai-fuan ida-idak nia laran; Espésie ne’e bele identifika husi ai-funan ne’ebé lisa kontráriu, ai-funan agrupamentu ki’ik ne’ebé nakukun ho idade, ai-fuan metan ki’ik sira, no fragrância ai-sandália ne’ebé forte husi ai-tahan.', 'Simples', 'Droga', 'Flores: Nov ba Dezembru; Ai-fuan: Marsu to’o Juñu 2019.', 'Sandalwood produz fini ki’ik, toos ne’ebé taka iha ai-fuan metan-roxu-lixu ne’ebé maduru iha tempu maran. Ai-fuan sira ne’ebé maduru rekolla diretamente husi ai-hun, hamoos hodi hasai pulpa, no ar-maran antes kuda. Fini sira moris di’ak liu iha meiu ida ne’ebé drenajen di’ak hanesan rai-henek ka rai-henek, rai úmidu maibé la’ós bee-matan. Jerminasaun baibain hahú iha semana 2–4 ​​nia laran iha kondisaun manas, ho sombra. Sandalwood hanesan espésie semi-parazita no presiza ai-horis hospedeiru ne’ebé adekuadu husi faze ai-horis sedu hodi fornese nutriente liu husi ligasaun haustoriál. Erva ka ai-horis ne’ebé buras lalais hanesan Alternathera, Cajanus etc baibain uza hanesan uma-na’in primáriu. Tenke kuda ai-oan iha sombra parsiál nia okos, ho rega ho kuidadu, to’o estabelese ona molok kuda to’os ho espésie uma-na’in ne’ebé adekuadu ba tempu naruk.', 'Album Santalum bele afetadu tebes husi “moras spike,” ne’ebé hada’et liu husi kontaktu abut no bele oho ai-horis iha tinan 1–2 nia laran hafoin sintoma hahú, no ai-funan bele hapara tau ai-fuan. Tanba laiha kura ne’ebé konfiavel bainhira ai-hun ida hetan infesaun, estratéjia di’ak liu mak prevensaun: mantein espasu di’ak (besik 5–6 m) no evita kuda besik liu. Haburas ai-sandália ho ai-horis kompañeiru/host ne’ebé adekuadu hanesan Casuarina, Acacia, ka Eucalyptus, enkuantu mantein ai-horis uma-na’in saudavel ho du’ut di’ak no sombra ba ai-oan. Redús mós insetu sira ne’ebé supa sap ne’ebé bele ajuda hada’et moras ne’e hodi uza protesaun rede/tetuk simples, liuliu iha ai-horis joven sira.', NULL),
(22, 'Swietenia macrophylla', 'Ai‐mahonia', 'Naran Swietenia nian hafoin Gerard (von) van Swieten, médiku no botásista olandés-austríaku ida, no makrofillla mai husi makros Gregu (“boot”) + phyllon (“daun”), refere ba ai-hun nia fulin/palfaun boot.', 'Makrofillla Swietenia hanesan ai-horis ida ne’ebé popular, la’ós nativa iha Timor-Leste, ne’ebé kuda barak iha área barak ba ninia ai-tahan ne’ebé iha valór.', 'Ai-horis boot ida ne’ebé moris lalais, ne’ebé moris lalais ba ai-hun semi-evergreen, baibain ho ai-tahan aas ida ne’ebé loos no koroa ida ne’ebé luan, kór-azul-azu-kafé no sai áspera no fissura ho idade; ai-tahan ne’e toos no dura, tipikamente mean-kafé; Husik kompostu (pinnate) no alterna, ho par balun ho panfletu boot, lisa, brillante, oval to’o ho forma lansa; Ai-funan ki’ik no verde-mutin ba kremosu, lori iha agrupamentu ramu ne’ebé loos (púniku), baibain fragrante kmaan; Fruta kapsula boot, toos, ai-tahan ne’ebé sai kór-kafé no fahe ba válvula oioin bainhira maduru; Fini barak, latan no papada ho ala naruk ba dispersaun anin; Espésie ne’e bele identifika husi ai-funan boot ne’ebé pinto ho folhetu brillante, kapsula ai-tahan boot ne’ebé fahe nakloke, no fini barak ho ala.', 'Kompostu ho maneira ne’ebé ho maneira ne’ebé ho maneira ne’ebé kompoin (ida de’it)', 'Kapsula', 'Flores: Jullu to’o Setembru; Frutador: Dezembru to’o Fevereiru 2019.', 'Kolekta fini husi ai-mahogany ne’ebé maduru (besik tinan 30–40), idealmente antes de’it tempu udan, no kuda sira lakleur hafoin rekolla ba rezultadu di’ak liu. Hafoin loro-matan maran, fini bele rai iha ar no hela viável liu fulan neen. Kuan fini ne’ebé laiha pre-tratamentu, tau sira ho kle’an (besik 0.5–1 cm) iha mistura viveiru ne’ebé drenadu ho di’ak (e.g., ai-tahan, kulit-koko, kaska ai-fuan ne’ebé rahun) iha naroman ne’ebé filtradu nia okos. Jerminasaun baibain akontese iha semana 2–3 nia laran, no ai-oan prontu atu transplanta bainhira sira to’o besik 15–20 cm aas.', 'Peste prinsipál mahogany nian mak borer filmajen mahogany (Hypsipyla robusta), ne’ebé nia larva bore ba iha musan leten ne’ebé ternu no kauza dieback. Ida ne’e hapara ai-hun atu labele moris loos, lori ba kresimentu ne’ebé todan no forma ida ne’ebé buras, ho ai-tahan barak. Atake sira baibain aat liu iha plantasaun monokultura no kondisaun manas, úmidu (besik 25–30°C). Reduz risku liu husi kahur espésie (intercropping ho ai-horis armadilha hanesan Toona ciliata ka Pterocarpus índico), hasai musan/larva infestadu, no kuda iha altitude kraik iha kraik 500 m. Prevene abut ne’ebé dodok liu husi rai rai ne’ebé drenajen di’ak, evita bee-matan, no fó ai-oan loro-matan ne’ebé natoon.', NULL);
